import type { ExportColumn } from "@/lib/feature-kit/export"
import type { ReactNode } from "react"

export type BulkActionBarProps = {
  children?: ReactNode
  className?: string
}

export type BulkExportActionProps<TData> = {
  /** Base filename without extension (e.g. `"users"`). */
  filename: string
  /** Columns included in the exported file. */
  columns: ExportColumn<TData>[]
  /** Button label. Falls back to a CSV/XLSX-specific default. */
  label?: string
  /** Confirmation dialog title. Falls back to `common.confirmAction`. */
  confirmTitle?: string
  /** Confirmation dialog body. Falls back to a count-based default. */
  confirmDescription?: string | ((selectedCount: number) => string)
  /** Primary action label in the confirmation dialog. */
  confirmLabel?: string
  className?: string
}

"use client"

import { X } from "lucide-react"
import { useTranslations } from "next-intl"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import { useDataTableContext } from "../core"
import { bulkActionButtonClassName } from "./constants"

type BulkClearSelectionActionProps = {
  className?: string
}

export function BulkClearSelectionAction({ className }: BulkClearSelectionActionProps) {
  const t = useTranslations()
  const { clearSelection } = useDataTableContext()

  return (
    <Button
      type="button"
      variant="outline"
      size="sm"
      className={cn(bulkActionButtonClassName, className)}
      onClick={clearSelection}
      aria-label={t("dataTable.selection.clearAria")}>
      <X data-icon="inline-start" />
      {t("dataTable.selection.clear")}
    </Button>
  )
}

"use client"

import dynamic from "next/dynamic"

import { BulkExportCsvActionSkeleton } from "./bulk-export-csv-action-skeleton"

export const BulkExportCsvAction = dynamic(
  () => import("./bulk-export-csv-action").then((mod) => mod.BulkExportCsvAction),
  {
    ssr: false,
    loading: () => <BulkExportCsvActionSkeleton />,
  },
)

import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"

type BulkExportCsvActionSkeletonProps = {
  className?: string
}

/** Matches `BulkExportCsvAction` button dimensions (`size="sm"`). */
export function BulkExportCsvActionSkeleton({ className }: BulkExportCsvActionSkeletonProps = {}) {
  return (
    <Skeleton
      className={cn("h-6 w-20 shrink-0 rounded-full", className)}
      aria-hidden="true"
    />
  )
}

"use client"

import type { BulkExportActionProps } from "./bulk-action-bar-types"

import { exportToCsv } from "@/lib/feature-kit/export"
import { useConfirmationDialog } from "@/lib/feature-kit/layout/confirmation-dialog"
import { FileSpreadsheet } from "lucide-react"
import { useTranslations } from "next-intl"
import { useCallback } from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import { useDataTableContext } from "../core"
import { bulkActionButtonClassName } from "./constants"

export function BulkExportCsvAction<TData>({
  filename,
  columns,
  label,
  confirmTitle,
  confirmDescription,
  confirmLabel,
  className,
}: BulkExportActionProps<TData>) {
  const t = useTranslations()
  const { confirm } = useConfirmationDialog()
  const { selectedRows, selectedCount } = useDataTableContext<TData>()

  const handleExport = useCallback(async () => {
    if (selectedCount === 0 || columns.length === 0) {
      return
    }

    const description =
      typeof confirmDescription === "function"
        ? confirmDescription(selectedCount)
        : (confirmDescription ?? t("dataTable.bulk.exportCsvConfirmDescription", { count: selectedCount }))

    const confirmed = await confirm({
      title: confirmTitle ?? t("dataTable.bulk.exportCsvConfirmTitle"),
      description,
      confirmLabel: confirmLabel ?? t("dataTable.bulk.exportConfirmAction"),
    })

    if (!confirmed) {
      return
    }

    exportToCsv(selectedRows, columns, filename)
  }, [columns, confirm, confirmDescription, confirmLabel, confirmTitle, filename, selectedCount, selectedRows, t])

  return (
    <Button
      type="button"
      variant="outline"
      size="sm"
      className={cn(bulkActionButtonClassName, className)}
      disabled={selectedCount === 0 || columns.length === 0}
      onClick={() => {
        void handleExport()
      }}>
      <FileSpreadsheet data-icon="inline-start" />
      {label ?? t("dataTable.bulk.exportCsv")}
    </Button>
  )
}

"use client"

import type { BulkExportActionProps } from "./bulk-action-bar-types"

import { exportToXlsx } from "@/lib/feature-kit/export"
import { useConfirmationDialog } from "@/lib/feature-kit/layout/confirmation-dialog"
import { FileSpreadsheet } from "lucide-react"
import { useTranslations } from "next-intl"
import { useCallback, useState } from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import { useDataTableContext } from "../core"
import { bulkActionButtonClassName } from "./constants"

export function BulkExportXlsxAction<TData>({
  filename,
  columns,
  label,
  confirmTitle,
  confirmDescription,
  confirmLabel,
  className,
}: BulkExportActionProps<TData>) {
  const t = useTranslations()
  const { confirm } = useConfirmationDialog()
  const { selectedRows, selectedCount } = useDataTableContext<TData>()
  const [isExporting, setIsExporting] = useState(false)

  const handleExport = useCallback(async () => {
    if (selectedCount === 0 || columns.length === 0) {
      return
    }

    const description =
      typeof confirmDescription === "function"
        ? confirmDescription(selectedCount)
        : (confirmDescription ?? t("dataTable.bulk.exportXlsxConfirmDescription", { count: selectedCount }))

    const confirmed = await confirm({
      title: confirmTitle ?? t("dataTable.bulk.exportXlsxConfirmTitle"),
      description,
      confirmLabel: confirmLabel ?? t("dataTable.bulk.exportConfirmAction"),
    })

    if (!confirmed) {
      return
    }

    setIsExporting(true)
    try {
      await exportToXlsx(selectedRows, columns, filename)
    } finally {
      setIsExporting(false)
    }
  }, [columns, confirm, confirmDescription, confirmLabel, confirmTitle, filename, selectedCount, selectedRows, t])

  return (
    <Button
      type="button"
      variant="outline"
      size="sm"
      className={cn(bulkActionButtonClassName, className)}
      disabled={selectedCount === 0 || columns.length === 0 || isExporting}
      onClick={() => {
        void handleExport()
      }}>
      <FileSpreadsheet data-icon="inline-start" />
      {label ?? t("dataTable.bulk.exportXlsx")}
    </Button>
  )
}

/** Shared compact styling for bulk action bar buttons (`size="sm"`, wrapping toolbar). */
export const bulkActionButtonClassName = "shrink-0 rounded-full"

/** Max height for the action row area: two `size="sm"` rows (h-8) plus one gap-y-1. */
export const bulkActionBarActionsMaxHeightClass = "max-h-[4.25rem]"

"use client"
// Reads the stable, in-place mutating TanStack column instance during render.
"use no memo"

import type { Column } from "@tanstack/react-table"
import type { LucideIcon } from "lucide-react"
import type { HTMLAttributes } from "react"

import { ArrowDown, ArrowUp, Funnel } from "lucide-react"
import { useTranslations } from "next-intl"
import { useState } from "react"

import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverHeader, PopoverTitle, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"

import { DATA_TABLE_FILTER_HEADER_WRAPPER_CLASS, DATA_TABLE_HEADER_TRIGGER_CLASS } from "../constants"
import { useDataTableContext } from "../core"
import {
  cycleSortDirection,
  FILTER_ACTIVE_DOT_CLASS,
  FilterPanelContent,
  findFilterDefinitionByColumnId,
  resolveDefinitionSortDirection,
  resolveFilterActiveState,
} from "../filter"
import { humanizeColumnId } from "../view-options/view-options-utils"
import { ColumnHeaderFunnelTrigger } from "./column-header-funnel-trigger"

type DataTableColumnHeaderAppearance = "table" | "toolbar"

interface DataTableColumnHeaderProps<TData, TValue> extends HTMLAttributes<HTMLDivElement> {
  column: Column<TData, TValue>
  title?: string
  titleKey?: string
  /**
   * @deprecated Ignored in table headers — the label already names the column, so type icons were
   * dropped for a quieter header. Still rendered by the legacy `appearance="toolbar"` trigger.
   */
  icon?: LucideIcon
  /** Table headers use ghost triggers; toolbar filters use outline to match view options. */
  appearance?: DataTableColumnHeaderAppearance
}

function resolveColumnTitle(t: ReturnType<typeof useTranslations>, titleKey: string, title?: string): string {
  if (t.has(titleKey)) {
    return t(titleKey)
  }
  if (title?.trim()) {
    return title
  }
  const leaf = titleKey.split(".").pop() ?? titleKey
  return humanizeColumnId(leaf)
}

function ColumnHeaderLabel({
  title,
  appearance = "table",
}: {
  title: string
  appearance?: DataTableColumnHeaderAppearance
}) {
  if (!title) {
    return null
  }
  return (
    <span
      className={cn(
        "inline-flex items-center whitespace-nowrap",
        appearance === "toolbar" ? "text-foreground" : "font-semibold text-foreground",
      )}>
      {title}
    </span>
  )
}

const TABLE_HEADER_FILTER_KINDS = ["search", "options"] as const

/**
 * Column header. Clicking the label cycles sort (asc → desc → none); the arrow shows only when
 * sorted (faint on hover). A separate funnel — visible on hover, or in info blue when this column
 * is filtered — opens a live search / values popover. No column-type icons.
 */
export function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  titleKey,
  icon,
  appearance = "table",
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  const t = useTranslations()
  const { filters, columnSearch, sorting = [], filterDefinitions, setSorting } = useDataTableContext<TData>()
  const [menuOpen, setMenuOpen] = useState(false)
  const displayTitle = titleKey ? resolveColumnTitle(t, titleKey, title) : (title ?? "")
  const definition = findFilterDefinitionByColumnId(filterDefinitions, column.id)

  if (!definition) {
    return (
      <div className={cn(className)}>
        <ColumnHeaderLabel
          title={displayTitle}
          appearance={appearance}
        />
      </div>
    )
  }

  const active = resolveFilterActiveState(definition, { filters, columnSearch, sorting })
  const menuTitle = displayTitle.trim() ? displayTitle : definition.label

  if (appearance === "toolbar") {
    return (
      <div className={cn("flex shrink-0", className)}>
        <Popover
          open={menuOpen}
          onOpenChange={setMenuOpen}>
          <PopoverTrigger asChild>
            <ColumnHeaderFunnelTrigger
              {...(icon ? { icon } : {})}
              title={displayTitle}
              activeCount={active.count}
              menuLabel={t("dataTable.column.filterMenuAria", { field: menuTitle, count: active.count })}
              appearance="toolbar"
              open={menuOpen}
            />
          </PopoverTrigger>
          <PopoverContent
            align="start"
            className="w-[min(20rem,calc(100vw-2rem))] gap-0 p-0">
            <PopoverHeader className="border-border border-b px-3 py-2.5">
              <PopoverTitle>{menuTitle}</PopoverTitle>
            </PopoverHeader>
            <FilterPanelContent
              definition={definition}
              menuOpen={menuOpen}
              onClose={() => setMenuOpen(false)}
            />
          </PopoverContent>
        </Popover>
      </div>
    )
  }

  // Table header: the label sorts on click, the funnel (search / values only) filters.
  const sortDirection = resolveDefinitionSortDirection(definition, sorting)
  const canSort = definition.sort && definition.columnId !== null
  const canFilter = definition.search || definition.options !== null
  const isFiltered = active.search || active.options
  const filterCount = Number(active.search) + Number(active.options)
  const SortIcon = sortDirection === "desc" ? ArrowDown : ArrowUp

  return (
    <div className={cn(DATA_TABLE_FILTER_HEADER_WRAPPER_CLASS, "group/header items-center gap-0.5", className)}>
      {canSort ? (
        <Button
          type="button"
          variant="ghost"
          className={cn(DATA_TABLE_HEADER_TRIGGER_CLASS, "group/sort gap-1")}
          aria-label={t("dataTable.column.sortAria", { field: menuTitle, direction: sortDirection ?? "none" })}
          onClick={() => {
            const next = cycleSortDirection(sortDirection)
            if (next && definition.columnId) {
              setSorting?.(definition.columnId, next)
            } else {
              setSorting?.(null, null)
            }
          }}>
          <span className="font-semibold text-foreground">{displayTitle}</span>
          <SortIcon
            data-icon="inline-end"
            aria-hidden
            className={cn(
              "size-3.5 transition-opacity",
              sortDirection ? "text-foreground opacity-100" : "opacity-0 group-hover/sort:opacity-40",
            )}
          />
        </Button>
      ) : (
        <ColumnHeaderLabel
          title={displayTitle}
          appearance={appearance}
        />
      )}
      {canFilter ? (
        <Popover
          open={menuOpen}
          onOpenChange={setMenuOpen}>
          <PopoverTrigger asChild>
            <Button
              type="button"
              variant="ghost"
              size="icon-xs"
              aria-expanded={menuOpen}
              aria-haspopup="dialog"
              aria-label={t("dataTable.column.filterMenuAria", { field: menuTitle, count: filterCount })}
              className={cn(
                "relative size-6 shrink-0 transition-opacity",
                isFiltered
                  ? "text-info opacity-100 hover:text-info"
                  : "text-muted-foreground opacity-0 focus-visible:opacity-100 group-hover/header:opacity-100 data-[state=open]:opacity-100 [@media(hover:none)]:opacity-60",
              )}>
              <Funnel
                className="size-3.5"
                aria-hidden
              />
              {isFiltered ? (
                <span
                  className={FILTER_ACTIVE_DOT_CLASS}
                  aria-hidden
                />
              ) : null}
            </Button>
          </PopoverTrigger>
          <PopoverContent
            align="start"
            className="w-[min(20rem,calc(100vw-2rem))] gap-0 p-0">
            <PopoverHeader className="border-border border-b px-3 py-2.5">
              <PopoverTitle>{menuTitle}</PopoverTitle>
            </PopoverHeader>
            <FilterPanelContent
              definition={definition}
              kinds={TABLE_HEADER_FILTER_KINDS}
              menuOpen={menuOpen}
              onClose={() => setMenuOpen(false)}
            />
          </PopoverContent>
        </Popover>
      ) : null}
    </div>
  )
}

"use client"

import type { ColumnDef } from "@tanstack/react-table"
import type { Route } from "next"
import type { ReactNode } from "react"

import { CurrencyCell, DateCell, NumberCell } from "format/ui"
import { Clock, ImageIcon, MoreHorizontal, Star } from "lucide-react"
import Link from "next/link"
import { useTranslations } from "next-intl"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import { DATA_TABLE_CELL_INSET_CLASS } from "../constants"
import { type RowActionComponent, RowActionsMenu } from "../row-action"
import { colorClass, displayTypeOptions, statusOptions, visibilityOptions } from "../utils"
import { DataTableColumnHeader } from "./column-data-table-column-header"
import { DataTableColumnFallbackText, DataTablePostsCountLabel } from "./column-data-table-fallback-text"
import { DataTableSelectAllCheckbox, DataTableSelectRowCheckbox } from "./column-data-table-select-checkboxes"
import { STICKY_CELL_CONTENT_CLASS } from "./column-sticky-classes"

const ColumnCell = ({ children, className }: { children: ReactNode; className?: string }) => {
  return (
    <div className={cn("line-clamp-1 gap-2 text-foreground text-sm", DATA_TABLE_CELL_INSET_CLASS, className)}>
      {children}
    </div>
  )
}
const keys = {
  ID: "id",
  SLUG: "slug",
  SELECT: "select",
  ACTIONS: "actions",
  VISIBILITY: "visibility",
  POSTS_COUNT: "postsCount",
  STATUS: "status",
  DESCRIPTION: "description",
  CREATED_AT: "createdAt",
  FULL_NAME: "fullName",
  DELETED_AT: "deletedAt",
  EMAIL: "email",
  NAME: "name",
  IMAGE: "image",
  DISPLAY_TYPE: "displayType",
  UPDATED_AT: "updatedAt",
  TITLE: "title",
  COLOR: "color",
  IS_FEATURED: "isFeatured",
  POPULARITY: "popularity",
  VALUE: "value",
  CURRENCY: "currency",
}

function idColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: keys.ID,
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.id"
        />
      ),
      cell: ({ row }) => {
        const id = String(row.getValue(keys.ID))
        return (
          <ColumnCell className="w-20">
            <Tooltip>
              <TooltipTrigger asChild>
                <div className="max-w-20 truncate text-muted-foreground text-sm">{id}</div>
              </TooltipTrigger>
              <TooltipContent>{id}</TooltipContent>
            </Tooltip>
          </ColumnCell>
        )
      },
    },
  ]
}
function titleColumn<T>(url: string): ColumnDef<T>[] {
  return [
    {
      accessorKey: keys.TITLE,
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.title"
        />
      ),
      cell: ({ row }) => {
        const rawTitle = row.getValue(keys.TITLE)
        const slug = row.getValue(keys.SLUG) as string
        if (rawTitle == null || rawTitle === "") {
          return (
            <ColumnCell className="min-w-55 text-muted-foreground text-sm">
              <DataTableColumnFallbackText messageKey="dataTable.column.notAvailable" />
            </ColumnCell>
          )
        }
        const title = String(rawTitle)
        return (
          <ColumnCell className="min-w-55">
            <Tooltip>
              <TooltipTrigger asChild>
                <Link
                  href={`${url}/${slug}` as Route}
                  className="max-w-55 truncate font-medium text-sm underline-offset-4 hover:underline">
                  {title}
                </Link>
              </TooltipTrigger>
              <TooltipContent>{title}</TooltipContent>
            </Tooltip>
          </ColumnCell>
        )
      },
    },
  ]
}
function selectColumn<T>({ selectAll = true }: { selectAll?: boolean } = {}): ColumnDef<T>[] {
  return [
    {
      id: keys.SELECT,
      meta: { sticky: "left", labelKey: "dataTable.column.selection", showSelectAllHeader: selectAll },
      header: selectAll ? ({ table }) => <DataTableSelectAllCheckbox table={table} /> : () => null,
      cell: ({ row }) => <DataTableSelectRowCheckbox row={row} />,
      enableSorting: false,
      enableHiding: false,
    },
  ]
}
function descriptionColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: keys.DESCRIPTION,
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.description"
        />
      ),
      cell: ({ row }) => {
        const rawDescription = row.getValue(keys.DESCRIPTION)
        const description = rawDescription == null || rawDescription === "" ? null : String(rawDescription)
        return (
          <ColumnCell className="min-w-55">
            <Tooltip>
              <TooltipTrigger asChild>
                <div className="max-w-55 truncate text-muted-foreground text-sm">
                  {description ?? <DataTableColumnFallbackText messageKey="dataTable.column.noDescription" />}
                </div>
              </TooltipTrigger>
              {description ? <TooltipContent>{description}</TooltipContent> : null}
            </Tooltip>
          </ColumnCell>
        )
      },
    },
  ]
}
function ActionsColumnHeader({ tooltipKey = "dataTable.column.rowActions" }: { tooltipKey?: string }) {
  const t = useTranslations()

  return (
    <div className={STICKY_CELL_CONTENT_CLASS}>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            type="button"
            className="inline-flex size-7 items-center justify-center"
            aria-label={t(tooltipKey)}>
            <MoreHorizontal
              className="size-4 text-muted-foreground"
              aria-hidden
            />
          </button>
        </TooltipTrigger>
        <TooltipContent>{t(tooltipKey)}</TooltipContent>
      </Tooltip>
    </div>
  )
}

function actionsColumn<T>(config: { actions: RowActionComponent<T>[]; headerTooltipKey?: string }): ColumnDef<T>[] {
  const { actions, headerTooltipKey } = config
  const labelKey = headerTooltipKey ?? "dataTable.column.rowActions"

  return [
    {
      id: keys.ACTIONS,
      meta: { sticky: "right", labelKey },
      enableSorting: false,
      enableHiding: false,
      header: () => <ActionsColumnHeader {...(headerTooltipKey ? { tooltipKey: headerTooltipKey } : {})} />,
      cell: ({ row }) => (
        <div className={STICKY_CELL_CONTENT_CLASS}>
          <RowActionsMenu
            row={row}
            actions={actions}
          />
        </div>
      ),
    },
  ]
}
function visibilityColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: keys.VISIBILITY,
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.visibility"
        />
      ),
      cell: ({ row }) => {
        const type = visibilityOptions.find((type) => type.value === row.getValue(keys.VISIBILITY))

        if (!type) return null

        return (
          <ColumnCell>
            <Badge variant={"outline"}>
              {type.icon ? (
                <type.icon
                  className="size-4"
                  data-icon="inline-start"
                />
              ) : null}
              {type.label}
            </Badge>
          </ColumnCell>
        )
      },

      filterFn: (row, id, value) => {
        const rowValue = row.getValue(id) ?? ""
        return (value as string[]).includes(rowValue as string)
      },
    },
  ]
}
function statusColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: keys.STATUS,
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.status"
        />
      ),
      cell: ({ row }) => {
        const status = statusOptions.find((status) => status.value === row.getValue(keys.STATUS))
        if (!status) return null
        return (
          <ColumnCell className="">
            <Badge variant={"outline"}>
              {status.icon ? (
                <status.icon
                  className="size-4"
                  data-icon="inline-start"
                />
              ) : null}
              <span>{status.label}</span>
            </Badge>
          </ColumnCell>
        )
      },

      filterFn: (row, id, value) => {
        const rowValue = row.getValue(id) ?? ""
        return (value as string[]).includes(rowValue as string)
      },
    },
  ]
}
function postsCountColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: "postsCount",
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.postsCount"
        />
      ),
      cell: ({ row }) => (
        <ColumnCell className="flex items-center">
          <Badge variant={"outline"}>
            <DataTablePostsCountLabel count={String(row.getValue(keys.POSTS_COUNT))} />
          </Badge>
        </ColumnCell>
      ),
    },
  ]
}
function createdAtColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: "createdAt",
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.createdAt"
        />
      ),
      cell: ({ row }) => {
        const date = new Date(row.getValue(keys.CREATED_AT))
        return (
          <ColumnCell className="flex w-45 flex-row">
            <Badge variant={"outline"}>
              <Clock
                className="size-4"
                data-icon="inline-start"
              />
              <DateCell
                value={date}
                format="table"
              />
            </Badge>
          </ColumnCell>
        )
      },
    },
  ]
}
function updatedAtColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: "updatedAt",
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.updatedAt"
        />
      ),
      cell: ({ row }) => {
        const date = new Date(row.getValue(keys.UPDATED_AT))
        return (
          <ColumnCell className="flex w-45 flex-row">
            <Badge variant={"outline"}>
              <Clock
                className="size-4"
                data-icon="inline-start"
              />
              <DateCell
                value={date}
                format="table"
              />
            </Badge>
          </ColumnCell>
        )
      },
    },
  ]
}
function deletedAtColumn<T>(): ColumnDef<T>[] {
  return [
    {
      accessorKey: keys.DELETED_AT,
      header: ({ column }) => (
        <DataTableColumnHeader
          column={column}
          titleKey="dataTable.column.deletedAt"
        />
      ),
      cell: ({ row }) => {
