import type { StoredFilterPreferences } from "./filter-types"

import { FILTER_STORAGE_KEY_PREFIX } from "./filter-constants"

export function getFilterStorageKey(tableId: string): string {
  return `${FILTER_STORAGE_KEY_PREFIX}${tableId}`
}

function parseStoredFilterPreferences(raw: unknown): StoredFilterPreferences | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return null
  }

  const added = (raw as Record<string, unknown>)["added"]
  if (!Array.isArray(added)) {
    return null
  }

  return {
    added: added.filter((entry): entry is string => typeof entry === "string" && entry.length > 0),
  }
}

/**
 * Read stored filter visibility for a table.
 * Returns `null` when missing, invalid, or storage is unavailable. Client-only.
 */
export function readStoredFilterPreferences(tableId: string): StoredFilterPreferences | null {
  if (typeof window === "undefined" || !tableId) {
    return null
  }

  try {
    const raw = localStorage.getItem(getFilterStorageKey(tableId))
    if (!raw) {
      return null
    }
    return parseStoredFilterPreferences(JSON.parse(raw))
  } catch {
    return null
  }
}

/** Persist filter visibility for a table. No-ops on failure. Never stores applied values. */
export function writeStoredFilterPreferences(tableId: string, preferences: StoredFilterPreferences): void {
  if (typeof window === "undefined" || !tableId) {
    return
  }

  try {
    localStorage.setItem(getFilterStorageKey(tableId), JSON.stringify({ added: preferences.added }))
  } catch {
    // Quota exceeded, private browsing, or disabled storage.
  }
}

/** Keep only stored keys that still resolve to a definition (removed columns are dropped), preserving order. */
export function pruneStoredFilterKeys(added: readonly string[], knownKeys: readonly string[]): string[] {
  const known = new Set(knownKeys)
  const result: string[] = []
  for (const key of added) {
    if (known.has(key) && !result.includes(key)) {
      result.push(key)
    }
  }
  return result
}

/** Resolve initial added keys from storage, pruned to the current definitions. Client-only. */
export function resolveInitialAddedFilterKeys(tableId: string | undefined, knownKeys: readonly string[]): string[] {
  if (!tableId) {
    return []
  }
  const stored = readStoredFilterPreferences(tableId)
  return pruneStoredFilterKeys(stored?.added ?? [], knownKeys)
}

/** Build stored `added` keys in definition order from a checkbox selection. */
export function buildAddedFilterKeysFromSelection(
  selected: ReadonlySet<string>,
  knownKeysInOrder: readonly string[],
): string[] {
  return knownKeysInOrder.filter((key) => selected.has(key))
}

"use client"

import type { ComponentType } from "react"
import type { DataTableFilterDefinition, DataTableFilterKind } from "./filter-types"

import { useDataTableContext } from "../core"
import { FilterOptionPanel } from "./filter-option-panel"
import { FilterSearchPanel } from "./filter-search-panel"
import { FilterSortPanel } from "./filter-sort-panel"
import { resolveDefinitionSortDirection } from "./utils"

/** Props every capability renderer receives. Applied state and setters come from the table context. */
export type FilterPanelProps = {
  definition: DataTableFilterDefinition
  menuOpen: boolean
  /** Close the hosting popover (Enter in search, or a sort pick). Filters apply live and keep it open. */
  onClose: () => void
}

function FilterSearchRenderer({ definition, menuOpen, onClose }: FilterPanelProps) {
  const { columnSearch, setColumnSearch } = useDataTableContext()
  const appliedValue = columnSearch?.[definition.key] ?? ""

  return (
    <FilterSearchPanel
      appliedValue={appliedValue}
      menuOpen={menuOpen}
      onApply={(value) => {
        setColumnSearch?.(definition.key, value)
      }}
      onClear={() => {
        setColumnSearch?.(definition.key, "")
      }}
      onDone={onClose}
    />
  )
}

function FilterSortRenderer({ definition, onClose }: FilterPanelProps) {
  const { sorting = [], setSorting } = useDataTableContext()
  const direction = resolveDefinitionSortDirection(definition, sorting)

  return (
    <FilterSortPanel
      direction={direction}
      onSort={(next) => {
        if (definition.columnId) {
          setSorting?.(definition.columnId, next)
        }
        onClose()
      }}
      onClear={() => {
        setSorting?.(null, null)
        onClose()
      }}
    />
  )
}

function FilterOptionsRenderer({ definition, menuOpen }: FilterPanelProps) {
  const { filters, setFilter } = useDataTableContext()
  const appliedValues = filters?.[definition.key] ?? []

  return (
    <FilterOptionPanel
      options={definition.options ?? []}
      multi={definition.multi}
      {...(definition.matchesValue ? { matchesValue: definition.matchesValue } : {})}
      title={definition.label}
      appliedValues={appliedValues}
      menuOpen={menuOpen}
      onApply={(values) => {
        setFilter?.(definition.key, values.length > 0 ? values : null)
      }}
      onClear={() => {
        setFilter?.(definition.key, null)
      }}
    />
  )
}

/**
 * Capability → renderer. Adding a new filter type means adding a kind here (and to
 * `DataTableFilterKind`), not a new per-table component.
 */
export const filterRenderers: Record<DataTableFilterKind, ComponentType<FilterPanelProps>> = {
  search: FilterSearchRenderer,
  sort: FilterSortRenderer,
  options: FilterOptionsRenderer,
}

"use client"

import { Search } from "lucide-react"
import { useTranslations } from "next-intl"
import { useEffect, useRef, useState } from "react"

import { Button } from "@/components/ui/button"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group"

import { DATA_TABLE_SEARCH_DEBOUNCE_MS } from "../constants/constants-search"
import { useDebouncedCallback } from "../utils/utils-use-debounced-callback"

export type FilterSearchPanelProps = {
  appliedValue: string
  menuOpen: boolean
  /** Placeholder override (defaults to the generic column search placeholder). */
  placeholder?: string
  /** Called (debounced) while typing, and immediately on Enter. */
  onApply: (value: string) => void
  onClear: () => void
  /** Called after Enter so the host popover can close. */
  onDone?: () => void
}

/** Live text search for one filter definition: applies as you type; Enter closes; Clear resets. */
export function FilterSearchPanel({
  appliedValue,
  menuOpen,
  placeholder,
  onApply,
  onClear,
  onDone,
}: FilterSearchPanelProps) {
  const t = useTranslations()
  const [draftValue, setDraftValue] = useState(appliedValue)
  const committedRef = useRef(appliedValue)
  const debouncedApply = useDebouncedCallback((value: string) => {
    committedRef.current = value.trim()
    onApply(value)
  }, DATA_TABLE_SEARCH_DEBOUNCE_MS)

  // Adopt the applied value only when it changes from outside (chip removed, clear all, back/forward).
  useEffect(() => {
    if (!menuOpen || appliedValue.trim() === committedRef.current) {
      return
    }
    committedRef.current = appliedValue.trim()
    debouncedApply.cancel()
    setDraftValue(appliedValue)
  }, [menuOpen, appliedValue, debouncedApply])

  const hasValue = draftValue.trim() !== "" || appliedValue.trim() !== ""

  return (
    <div className="flex flex-col gap-1.5 p-2">
      <InputGroup className="bg-background shadow-xs">
        <InputGroupAddon align="inline-start">
          <Search className="size-3.5" />
        </InputGroupAddon>
        <InputGroupInput
          autoFocus
          value={draftValue}
          placeholder={placeholder ?? t("dataTable.column.columnSearchPlaceholder")}
          onChange={(event) => {
            setDraftValue(event.target.value)
            debouncedApply(event.target.value)
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault()
              debouncedApply.cancel()
              committedRef.current = draftValue.trim()
              onApply(draftValue)
              onDone?.()
            }
          }}
        />
      </InputGroup>
      {hasValue ? (
        <div className="flex justify-end">
          <Button
            type="button"
            variant="link"
            size="sm"
            className="h-auto p-0 text-muted-foreground text-xs"
            onClick={() => {
              debouncedApply.cancel()
              committedRef.current = ""
              setDraftValue("")
              onClear()
            }}>
            {t("dataTable.column.clearSearch")}
          </Button>
        </div>
      ) : null}
    </div>
  )
}

"use client"

import { ArrowDown, ArrowUp, X } from "lucide-react"
