/** Sort asc / desc buttons (plus clear when sorted) for one filter definition. */
export function FilterSortPanel({ direction, onSort, onClear }: FilterSortPanelProps) {
  const t = useTranslations()

  return (
    <div className="flex flex-col gap-1 p-2">
      <Button
        type="button"
        variant="ghost"
        aria-pressed={direction === "asc"}
        className="justify-start aria-pressed:bg-muted"
        onClick={() => onSort("asc")}>
        <ArrowUp data-icon="inline-start" />
        {t("dataTable.column.sortAsc")}
      </Button>
      <Button
        type="button"
        variant="ghost"
        aria-pressed={direction === "desc"}
        className="justify-start aria-pressed:bg-muted"
        onClick={() => onSort("desc")}>
        <ArrowDown data-icon="inline-start" />
        {t("dataTable.column.sortDesc")}
      </Button>
      {direction ? (
        <Button
          type="button"
          variant="ghost"
          className="justify-start"
          onClick={onClear}>
          <X data-icon="inline-start" />
          {t("dataTable.column.clearSort")}
        </Button>
      ) : null}
    </div>
  )
}

import type { ColumnFilterConfig, ColumnFilterOption } from "../view-options/view-options-types"

/** Independent capabilities a table filter definition can expose. */
export type DataTableFilterKind = "search" | "sort" | "options"

/**
 * Column-declared filter capabilities (`meta.filter`).
 *
 * Each capability is independent: a description column may enable `search` + `sort`
 * only, while an enum column enables `options` (distinct values) + `sort`.
 */
export type DataTableColumnFilterMeta = {
  /** URL key for option filters and column search (`cs.<key>`). Defaults to the column id. */
  key?: string
  /** Column-specific text search (`cs.<key>` URL param). */
  search?: boolean
  /** Sort asc/desc controls (`sortBy=<columnId>&sortDir=asc|desc`). */
  sort?: boolean
  /** Checkbox list of distinct values. Options come from `DataTable filterOptions[key]` or `staticOptions`. */
  options?: boolean
  /** When true (default), multiple values are stored as repeated URL params. */
  multi?: boolean
  /** Match applied URL values to option values (defaults to strict equality). */
  matchesValue?: (appliedValue: string, optionValue: string) => boolean
  /** Options declared inline when the table has no `filterOptions` record for this key. */
  staticOptions?: ColumnFilterOption[]
}

/** Accepted `meta.filter` shapes — the new capability meta or the legacy `{ urlKey, options }` config. */
export type DataTableColumnFilterInput = DataTableColumnFilterMeta | ColumnFilterConfig

/** Resolved, ready-to-render filter definition shared by header popovers and toolbar chips. */
export type DataTableFilterDefinition = {
  /** URL key (also the `filterOptions` record key). */
  key: string
  /** Owning column id, or `null` for toolbar-only definitions. */
  columnId: string | null
  /** Translated display label. */
  label: string
  search: boolean
  sort: boolean
  /** Distinct option list, or `null` when the definition does not expose an option filter. */
  options: ColumnFilterOption[] | null
  multi: boolean
  matchesValue?: (appliedValue: string, optionValue: string) => boolean
}

/** Which capabilities of a definition currently have applied state. */
export type DataTableFilterActiveState = {
  search: boolean
  sort: boolean
  options: boolean
  any: boolean
  /** Number of active capabilities (for accessible labels). */
  count: number
}

/** Persisted per-table filter visibility. Applied values never live here — only the URL owns them. */
export type StoredFilterPreferences = {
  /** Filter keys the user added to the toolbar chip row, in display order. */
  added: string[]
}

/** Sorting entry as exposed by TanStack (`{ id, desc }`). */
export type DataTableSortingEntry = { id: string; desc: boolean }

/** Applied state a filter renderer reads from the table context. */
export type DataTableFilterAppliedState = {
  filters: Record<string, string[]> | undefined
  columnSearch: Record<string, string> | undefined
  sorting: readonly DataTableSortingEntry[]
}

"use client"

import type { DataTableFilterDefinition } from "../filter-types"

import { useCallback, useEffect, useMemo, useState } from "react"

import { useViewOptionsMounted } from "../../view-options"
import {
  buildAddedFilterKeysFromSelection,
  resolveInitialAddedFilterKeys,
  writeStoredFilterPreferences,
} from "../filter-persistence"
import { getToolbarChipKeysFromDefinitions } from "../utils"

export type UseAddedFiltersOptions = {
  tableId: string | undefined
  definitions: readonly DataTableFilterDefinition[]
}

export type UseAddedFiltersResult = {
  /** False during SSR / first client render, before localStorage is read. */
  mounted: boolean
  addedKeys: string[]
  addFilter: (key: string) => void
  removeFilter: (key: string) => void
  /** Replace toolbar visibility preferences (localStorage `added` only). */
  setAddedFilterKeys: (keys: readonly string[]) => void
}

/**
 * Owns toolbar filter *visibility* (`localStorage` per `tableId`). Applied values stay in the URL.
 * Without a `tableId`, added filters live only for the current mount.
 */
export function useAddedFilters({ tableId, definitions }: UseAddedFiltersOptions): UseAddedFiltersResult {
  const mounted = useViewOptionsMounted()
  // Search-only filters (e.g. "Created by") can be added as chips too, not just value lists.
  const optionKeys = useMemo(() => getToolbarChipKeysFromDefinitions(definitions), [definitions])
  const optionKeysSignature = optionKeys.join("\0")
  const [addedKeys, setAddedKeys] = useState<string[]>([])

  useEffect(() => {
    if (!tableId) {
      return
    }
    setAddedKeys(resolveInitialAddedFilterKeys(tableId, optionKeysSignature.split("\0").filter(Boolean)))
  }, [tableId, optionKeysSignature])

  const persist = useCallback(
    (next: string[]) => {
      if (tableId) {
        writeStoredFilterPreferences(tableId, { added: next })
      }
    },
    [tableId],
  )

  const addFilter = useCallback(
    (key: string) => {
      setAddedKeys((current) => {
        if (current.includes(key)) {
          return current
        }
        const next = [...current, key]
        persist(next)
        return next
      })
    },
    [persist],
  )

  const removeFilter = useCallback(
    (key: string) => {
      setAddedKeys((current) => {
        if (!current.includes(key)) {
          return current
        }
        const next = current.filter((entry) => entry !== key)
        persist(next)
        return next
      })
    },
    [persist],
  )

  const setAddedFilterKeys = useCallback(
    (keys: readonly string[]) => {
      const next = buildAddedFilterKeysFromSelection(new Set(keys), optionKeys)
      setAddedKeys(next)
      persist(next)
    },
    [optionKeys, persist],
  )

  return { mounted, addedKeys, addFilter, removeFilter, setAddedFilterKeys }
}

import type {
  DataTableFilterActiveState,
  DataTableFilterAppliedState,
  DataTableFilterDefinition,
  DataTableSortingEntry,
} from "../filter-types"

/** Current sort direction for a definition's column, or `null`. */
export function resolveDefinitionSortDirection(
  definition: Pick<DataTableFilterDefinition, "columnId" | "sort">,
  sorting: readonly DataTableSortingEntry[],
): "asc" | "desc" | null {
  if (!definition.sort || !definition.columnId) {
    return null
  }
  const entry = sorting.find((item) => item.id === definition.columnId)
  if (!entry) {
    return null
  }
  return entry.desc ? "desc" : "asc"
}

/** Header click cycle: unsorted → ascending → descending → unsorted. */
export function cycleSortDirection(current: "asc" | "desc" | null): "asc" | "desc" | null {
  if (current === null) {
    return "asc"
  }
  return current === "asc" ? "desc" : null
}

/** Which capabilities of a definition currently hold applied state (URL or local). */
export function resolveFilterActiveState(
  definition: DataTableFilterDefinition,
  applied: DataTableFilterAppliedState,
): DataTableFilterActiveState {
  const search = definition.search && (applied.columnSearch?.[definition.key]?.trim() ?? "") !== ""
  const sort = resolveDefinitionSortDirection(definition, applied.sorting) !== null
  const options = definition.options !== null && (applied.filters?.[definition.key]?.length ?? 0) > 0
  const count = Number(search) + Number(sort) + Number(options)

  return { search, sort, options, any: count > 0, count }
}

/** Option-capable definition keys that currently have applied values. */
export function getAppliedOptionFilterKeys(
  definitions: readonly DataTableFilterDefinition[],
  filters: Record<string, string[]> | undefined,
): string[] {
  if (!filters) {
    return []
  }
  return definitions
    .filter((definition) => definition.options !== null && (filters[definition.key]?.length ?? 0) > 0)
    .map((definition) => definition.key)
}

/**
 * Chip keys to show in the toolbar: user-added (localStorage) in stored order, then any applied
 * keys not yet listed. `pinnedKeys` does not force visibility — it only marks chips non-removable
 * when they appear via added or applied state.
 */
export function resolveVisibleFilterChipKeys(input: {
  definitions: readonly DataTableFilterDefinition[]
  addedKeys: readonly string[]
  appliedKeys: readonly string[]
  /** Accepted for API stability; ignored for visibility (see toolbar chip removable flag). */
  pinnedKeys?: readonly string[]
  /** Keys allowed as chips. Defaults to every option-capable definition. */
  candidateKeys?: readonly string[]
}): string[] {
  const optionKeys = new Set(
    input.candidateKeys ??
      input.definitions.filter((definition) => definition.options !== null).map((definition) => definition.key),
  )
  const result: string[] = []
  const seen = new Set<string>()

  for (const key of [...input.addedKeys, ...input.appliedKeys]) {
    if (!optionKeys.has(key) || seen.has(key)) {
      continue
    }
    seen.add(key)
    result.push(key)
  }

  return result
}

import type { ColumnFilterConfig, ColumnFilterOption, DataTableColumnMeta, TranslateFn } from "../../view-options"
import type {
  DataTableColumnFilterInput,
  DataTableColumnFilterMeta,
  DataTableFilterDefinition,
  DataTableFilterKind,
} from "../filter-types"

import { humanizeColumnId } from "../../view-options"

/** Minimal column-def shape needed to resolve filter definitions (no table instance required). */
export type FilterColumnDefLike = {
  id?: unknown
  accessorKey?: unknown
  accessorFn?: unknown
  enableSorting?: boolean
  header?: unknown
  meta?: unknown
}

export type ResolveFilterDefinitionsOptions = {
  /** Distinct option lists keyed by filter key (full dataset, resolved by the page). */
  filterOptions?: Record<string, ColumnFilterOption[]> | undefined
  /** Definitions declared outside column meta (toolbar-only filters). Same key overrides the column one. */
  explicitDefinitions?: readonly DataTableFilterDefinition[] | undefined
  t: TranslateFn
}

function isLegacyFilterConfig(input: DataTableColumnFilterInput): input is ColumnFilterConfig {
  return typeof (input as ColumnFilterConfig).urlKey === "string"
}

/** Normalise legacy `{ urlKey, options }` into capability meta; new meta passes through. */
export function normalizeColumnFilterMeta(
  input: DataTableColumnFilterInput | undefined,
): DataTableColumnFilterMeta | undefined {
  if (!input) {
    return undefined
  }

  if (isLegacyFilterConfig(input)) {
    return {
      key: input.urlKey,
      options: true,
      staticOptions: input.options,
      ...(input.multi !== undefined ? { multi: input.multi } : {}),
      ...(input.matchesValue ? { matchesValue: input.matchesValue } : {}),
    }
  }

  return input
}

export function readColumnDefId(column: FilterColumnDefLike): string | null {
  if (typeof column.id === "string" && column.id) {
    return column.id
  }
  if (typeof column.accessorKey === "string" && column.accessorKey) {
    return column.accessorKey
  }
  return null
}

function readColumnDefMeta(column: FilterColumnDefLike): DataTableColumnMeta | undefined {
  return column.meta as DataTableColumnMeta | undefined
}

/** Def-level label resolution mirroring `resolveColumnLabel` (which needs a live column). */
export function resolveColumnDefLabel(column: FilterColumnDefLike, columnId: string, t: TranslateFn): string {
  const meta = readColumnDefMeta(column)

  if (meta?.labelKey) {
    if (t.has?.(meta.labelKey)) {
      return t(meta.labelKey)
    }
    if (!t.has) {
      try {
        return t(meta.labelKey)
      } catch {
        // Missing translation key — fall through.
      }
    }
  }

  if (meta?.label) {
    return meta.label
  }

  if (typeof column.header === "string" && column.header.trim()) {
    return column.header
  }

  return humanizeColumnId(columnId)
}

/** TanStack enables sorting for accessor columns unless `enableSorting: false`. */
function columnDefCanSort(column: FilterColumnDefLike): boolean {
  if (column.enableSorting === false) {
    return false
  }
  return typeof column.accessorKey === "string" || typeof column.accessorFn === "function"
}

/**
 * Resolve one filter definition from a column def, or `null` when the column exposes no capability.
 *
 * Legacy defaults (no `meta.filter`): sort follows `enableSorting`, search is opt-in via
 * `meta.search === true` (the column search param is backend-specific).
 */
export function resolveColumnFilterDefinition(
  column: FilterColumnDefLike,
  options: Pick<ResolveFilterDefinitionsOptions, "filterOptions" | "t">,
): DataTableFilterDefinition | null {
  const columnId = readColumnDefId(column)
  if (!columnId) {
    return null
  }

  const meta = readColumnDefMeta(column)
  const filterMeta = normalizeColumnFilterMeta(meta?.filter)
  const key = filterMeta?.key ?? columnId
  const canSort = columnDefCanSort(column)

  const sort = filterMeta?.sort ?? (meta?.sort === undefined ? canSort : meta.sort && canSort)
  const search = filterMeta?.search ?? meta?.search === true
  const wantsOptions = filterMeta?.options === true
  const optionList = wantsOptions ? (options.filterOptions?.[key] ?? filterMeta?.staticOptions ?? []) : null

  if (!sort && !search && !wantsOptions) {
    return null
  }

  return {
    key,
    columnId,
    label: resolveColumnDefLabel(column, columnId, options.t),
    search,
    sort,
    options: optionList,
    multi: filterMeta?.multi !== false,
    ...(filterMeta?.matchesValue ? { matchesValue: filterMeta.matchesValue } : {}),
  }
}

/**
 * Resolve every filter definition for a table: column-declared capabilities plus explicit
 * toolbar-only definitions. One definition per key; explicit definitions win.
 */
export function resolveFilterDefinitions(
  columns: readonly FilterColumnDefLike[],
  options: ResolveFilterDefinitionsOptions,
): DataTableFilterDefinition[] {
  const byKey = new Map<string, DataTableFilterDefinition>()

  for (const column of columns) {
    const definition = resolveColumnFilterDefinition(column, options)
    if (definition && !byKey.has(definition.key)) {
      byKey.set(definition.key, definition)
    }
  }

  for (const definition of options.explicitDefinitions ?? []) {
    byKey.set(definition.key, definition)
  }

  return Array.from(byKey.values())
}

/** URL keys of option-capable definitions (what `filters` reads from the URL). */
export function getFilterUrlKeysFromDefinitions(definitions: readonly DataTableFilterDefinition[]): string[] {
  return definitions.filter((definition) => definition.options !== null).map((definition) => definition.key)
}

/** Keys that can be added as toolbar chips: value-list and text-search filters. */
export function getToolbarChipKeysFromDefinitions(definitions: readonly DataTableFilterDefinition[]): string[] {
  return definitions
    .filter((definition) => definition.options !== null || definition.search)
    .map((definition) => definition.key)
}

/** Definitions that can render a toolbar chip / header option list. */
export function getOptionFilterDefinitions(
  definitions: readonly DataTableFilterDefinition[],
): DataTableFilterDefinition[] {
  return definitions.filter((definition) => definition.options !== null)
}

export function findFilterDefinitionByColumnId(
  definitions: readonly DataTableFilterDefinition[] | undefined,
  columnId: string,
): DataTableFilterDefinition | undefined {
  return definitions?.find((definition) => definition.columnId === columnId)
}

export function findFilterDefinitionByKey(
  definitions: readonly DataTableFilterDefinition[] | undefined,
  key: string,
): DataTableFilterDefinition | undefined {
  return definitions?.find((definition) => definition.key === key)
}

/** Capabilities a definition enables, in render order. */
export function getEnabledFilterKinds(
  definition: DataTableFilterDefinition,
  allowed?: readonly DataTableFilterKind[],
): DataTableFilterKind[] {
  const kinds: DataTableFilterKind[] = []
  if (definition.search) kinds.push("search")
  if (definition.sort) kinds.push("sort")
  if (definition.options !== null) kinds.push("options")
  if (!allowed) {
    return kinds
  }
  const allowedSet = new Set(allowed)
  return kinds.filter((kind) => allowedSet.has(kind))
}

import type { DataTableFilterDefinition } from "../filter-types"

import { DATA_TABLE_CLEAR_FILTER_URL_KEYS } from "../../constants"
import { FILTER_COLUMN_SEARCH_PARAM_PREFIX, FILTER_RESERVED_URL_KEYS } from "../filter-constants"

type SearchParamReader = Pick<URLSearchParams, "get">

/** `cs.<key>` — URL param carrying a column-specific text search. */
export function columnSearchParamKey(key: string): string {
  return `${FILTER_COLUMN_SEARCH_PARAM_PREFIX}${key}`
}

/** Inverse of {@link columnSearchParamKey}; `null` when the param is not a column search. */
export function filterKeyFromColumnSearchParam(param: string): string | null {
  if (!param.startsWith(FILTER_COLUMN_SEARCH_PARAM_PREFIX)) {
    return null
  }
  const key = param.slice(FILTER_COLUMN_SEARCH_PARAM_PREFIX.length)
  return key.length > 0 ? key : null
}

/** Read non-empty `cs.<key>` values for the given keys. */
export function readColumnSearchFromSearchParams(
  searchParams: SearchParamReader,
  keys: readonly string[],
): Record<string, string> {
  const result: Record<string, string> = {}
  for (const key of keys) {
    const value = searchParams.get(columnSearchParamKey(key))?.trim()
    if (value) {
      result[key] = value
    }
  }
  return result
}

/** Keys of definitions that expose column search. */
export function getColumnSearchKeysFromDefinitions(definitions: readonly DataTableFilterDefinition[]): string[] {
  return definitions.filter((definition) => definition.search).map((definition) => definition.key)
}

/** Sort keys are only cleared when explicitly requested. */
const SORT_URL_KEYS = new Set<string>(["sortBy", "sortDir"])

/**
 * Every URL key "Clear filters" removes for a table: definition keys, their `cs.*` params,
 * global `q`, and the legacy shared list (minus sort unless `includeSort`).
 */
export function collectClearableFilterKeys(
  definitions: readonly DataTableFilterDefinition[],
  options: { includeSort?: boolean; extraKeys?: readonly string[] } = {},
): string[] {
  const keys = new Set<string>()

  for (const definition of definitions) {
    if (definition.options !== null) {
      keys.add(definition.key)
    }
    if (definition.search) {
      keys.add(columnSearchParamKey(definition.key))
    }
  }

  keys.add("q")

  for (const key of DATA_TABLE_CLEAR_FILTER_URL_KEYS) {
    keys.add(key)
  }

  for (const key of options.extraKeys ?? []) {
    keys.add(key)
  }

  for (const key of FILTER_RESERVED_URL_KEYS) {
    if (key === "q") {
      continue
    }
    if (SORT_URL_KEYS.has(key) && options.includeSort) {
      continue
    }
    keys.delete(key)
  }

  return Array.from(keys)
}

