"use client"

import type { Row } from "@tanstack/react-table"

import { useDataTableContext } from "../core"
import { resolveSelectionKey } from "./selection-cross-page-types"

/** Whether a row is in the cross-page selection store (re-renders when selection changes). */
export function useIsRowSelected<TData>(row: Row<TData>): boolean {
  const { selectionKey, selectedRows } = useDataTableContext<TData>()
  const rowKey = resolveSelectionKey(selectionKey, row.original)
  return selectedRows.some((selected) => resolveSelectionKey(selectionKey, selected) === rowKey)
}

/** Page-level select-all checkbox state derived from the selection store. */
export function usePageSelectionCheckboxState<TData>(rows: Row<TData>[]) {
  const { selectionKey, selectedRows } = useDataTableContext<TData>()
  const selectedKeys = new Set(selectedRows.map((row) => resolveSelectionKey(selectionKey, row)))
  const selectableRows = rows.filter((row) => row.getCanSelect())
  const selectedOnPage = selectableRows.filter((row) =>
    selectedKeys.has(resolveSelectionKey(selectionKey, row.original)),
  )
  const allPageSelected = selectableRows.length > 0 && selectedOnPage.length === selectableRows.length
  const somePageSelected = selectedOnPage.length > 0 && !allPageSelected

  return { allPageSelected, somePageSelected }
}

"use client"

import type { OnChangeFn, RowSelectionState } from "@tanstack/react-table"
import type { CrossPageSelectionState, SelectionKey } from "./selection-cross-page-types"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"

import { resolveSelectionKey } from "./selection-cross-page-types"

export function useCrossPageSelection<TData>({
  selectionKey,
  data,
}: {
  selectionKey: SelectionKey<TData>
  data: TData[]
}): CrossPageSelectionState<TData> {
  const [selectedMap, setSelectedMap] = useState(() => new Map<string, TData>())
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({})
  const selectedMapRef = useRef(selectedMap)
  selectedMapRef.current = selectedMap

  const getRowKey = useCallback((row: TData) => resolveSelectionKey(selectionKey, row), [selectionKey])

  const getRowId = useCallback((row: TData) => getRowKey(row), [getRowKey])

  // Reconcile TanStack page selection when paginated data changes.
  useEffect(() => {
    const pageSelection: RowSelectionState = {}
    for (const row of data) {
      const key = getRowKey(row)
      if (selectedMapRef.current.has(key)) {
        pageSelection[key] = true
      }
    }
    setRowSelection(pageSelection)
  }, [data, getRowKey])

  const onRowSelectionChange: OnChangeFn<RowSelectionState> = useCallback((updater) => {
    setRowSelection((prev) => (typeof updater === "function" ? updater(prev) : updater))
  }, [])

  // Keep cross-page selection map in sync with current-page checkbox changes.
  useEffect(() => {
    setSelectedMap((map) => {
      let changed = false
      const nextMap = new Map(map)

      for (const row of data) {
        const key = getRowKey(row)
        const selected = Boolean(rowSelection[key])

        if (selected) {
          if (!nextMap.has(key) || nextMap.get(key) !== row) {
            nextMap.set(key, row)
            changed = true
          }
        } else if (nextMap.has(key)) {
          nextMap.delete(key)
          changed = true
        }
      }

      return changed ? nextMap : map
    })
  }, [data, getRowKey, rowSelection])

  const clearSelection = useCallback(() => {
    setSelectedMap(new Map())
    setRowSelection({})
  }, [])

  const selectedRows = useMemo(() => Array.from(selectedMap.values()), [selectedMap])
  const selectedCount = selectedMap.size

  return {
    selectionKey,
    selectedRows,
    selectedCount,
    rowSelection,
    onRowSelectionChange,
    getRowId,
    clearSelection,
  }
}

"use client"

import type { Column } from "@tanstack/react-table"
import type { ComponentType } from "react"

import { PlusCircle } from "lucide-react"
import { useTranslations } from "next-intl"
import { useMemo, useState } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command"
import { Popover, PopoverContent, PopoverHeader, PopoverTitle, PopoverTrigger } from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import {
  MULTI_SELECT_TRIGGER_BADGE_CLASS,
  MULTI_SELECT_TRIGGER_BADGE_COUNT_CLASS,
} from "@/lib/multi-select-badge"
import { cn } from "@/lib/utils"

interface DataTableFacetedFilterProps<TData, TValue> {
  column?: Column<TData, TValue>
  title?: string
  options: {
    label: string
    value: string
    color: string
    icon?: ComponentType<{ className?: string }>
  }[]
  value?: string | null
  onSelect?: (value: string | null) => void
}

export function DataTableFacetedFilter<TData, TValue>({
  column,
  title,
  options,
  value = null,
  onSelect,
}: DataTableFacetedFilterProps<TData, TValue>) {
  const t = useTranslations()
  const [open, setOpen] = useState(false)
  const facets = column?.getFacetedUniqueValues()
  const selectedValues = useMemo(() => {
    if (value !== undefined) {
      return new Set(value ? [value] : [])
    }
    return new Set((column?.getFilterValue() as string[] | undefined) ?? [])
  }, [value, column])

  const clearSelection = () => {
    if (onSelect) {
      onSelect(null)
    } else {
      column?.setFilterValue(undefined)
    }
    setOpen(false)
  }

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          aria-expanded={open}
          className="h-8 border">
          <PlusCircle data-icon="inline-start" />
          {title}
          {selectedValues.size > 0 ? (
            <>
              <Separator
                orientation="vertical"
                className="mx-2 h-4"
              />
              <Badge
                variant="default"
                className={cn(MULTI_SELECT_TRIGGER_BADGE_COUNT_CLASS, "lg:hidden")}>
                {selectedValues.size}
              </Badge>
              <div className="hidden gap-1 lg:flex">
                {selectedValues.size > 2 ? (
                  <Badge
                    variant="default"
                    className={MULTI_SELECT_TRIGGER_BADGE_CLASS}>
                    {t("dataTable.filter.selectedCount", { count: selectedValues.size })}
                  </Badge>
                ) : (
                  options
                    .filter((option) => selectedValues.has(option.value))
                    .map((option) => (
                      <Badge
                        variant="default"
                        key={option.value}
                        className={cn(MULTI_SELECT_TRIGGER_BADGE_CLASS, option.color)}>
                        {option.label}
                      </Badge>
                    ))
                )}
              </div>
            </>
          ) : null}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-[min(20rem,calc(100vw-2rem))] gap-0 p-0">
        <PopoverHeader className="border-border border-b px-3 py-2.5">
          <PopoverTitle>{title ?? t("dataTable.column.filter")}</PopoverTitle>
        </PopoverHeader>
        <Command>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandEmpty>{t("common.noResults")}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selectedValues.has(option.value)
                return (
                  <CommandItem
                    key={option.value}
                    onSelect={() => {
                      if (onSelect) {
                        onSelect(isSelected ? null : option.value)
                        setOpen(false)
                        return
                      }
                      const nextValues = new Set(selectedValues)
                      if (isSelected) {
                        nextValues.delete(option.value)
                      } else {
                        nextValues.add(option.value)
                      }
                      const filterValues = Array.from(nextValues)
                      column?.setFilterValue(filterValues.length ? filterValues : undefined)
                    }}>
                    <Checkbox
                      checked={isSelected}
                      className="pointer-events-none"
                      tabIndex={-1}
                      aria-hidden
                    />
                    {option.icon ? <option.icon className={cn("size-4", option.color)} /> : null}
                    <span>{option.label}</span>
                    {facets?.get(option.value) ? (
                      <span className="ms-auto flex size-4 items-center justify-center text-xs">
                        {facets.get(option.value)}
                      </span>
                    ) : null}
                  </CommandItem>
                )
              })}
            </CommandGroup>
            {selectedValues.size > 0 ? (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem
                    onSelect={clearSelection}
                    className="justify-center text-center">
                    {t("dataTable.filter.clear")}
                  </CommandItem>
                </CommandGroup>
              </>
            ) : null}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

