}

/** Wraps filter option content so table cell wrappers do not inflate chip/menu rows. */
export function DataTableFilterContent({ children, className }: DataTableFilterContentProps) {
  return <span className={cn(DATA_TABLE_FILTER_CONTENT_CLASS, className)}>{children}</span>
}

import type { Column, Table } from "@tanstack/react-table"
import type { DataTableFilterDefinition } from "../../filter"
import type { ColumnFilterOption, DataTableColumnMeta } from "../../view-options"

import { normalizeColumnFilterMeta } from "../../filter"
import { resolveColumnLabel } from "../../view-options"

export type AppliedFilterValue = {
  /** Stable React key for this value chip. */
  id: string
  value: string
  option: ColumnFilterOption | undefined
}

export type AppliedFilterGroup = {
  urlKey: string
  fieldLabel: string
  values: AppliedFilterValue[]
  /** `options` (repeated `<key>=v` params) or `search` (single `cs.<key>` text). Defaults to `options`. */
  kind?: "options" | "search"
}

/**
 * Build applied groups from resolved filter definitions: option values first, then column searches.
 * This is the definition-driven replacement for {@link resolveAppliedFilterGroups}.
 */
export function resolveAppliedFilterGroupsFromDefinitions(
  definitions: readonly DataTableFilterDefinition[] | undefined,
  filters: Record<string, string[]> | undefined,
  columnSearch: Record<string, string> | undefined,
): AppliedFilterGroup[] {
  if (!definitions) {
    return []
  }

  const groups: AppliedFilterGroup[] = []

  for (const definition of definitions) {
    if (definition.options === null) {
      continue
    }
    const appliedValues = filters?.[definition.key] ?? []
    if (appliedValues.length === 0) {
      continue
    }
    const matchesValue = definition.matchesValue ?? ((applied, option) => applied === option)
    const options = definition.options
    groups.push({
      urlKey: definition.key,
      fieldLabel: definition.label,
      kind: "options",
      values: appliedValues.map((value) => ({
        id: `${definition.key}:${value}`,
        value,
        option: options.find((entry) => matchesValue(value, entry.value)),
      })),
    })
  }

  for (const definition of definitions) {
    if (!definition.search) {
      continue
    }
    const text = columnSearch?.[definition.key]?.trim()
    if (!text) {
      continue
    }
    groups.push({
      urlKey: definition.key,
      fieldLabel: definition.label,
      kind: "search",
      values: [{ id: `cs:${definition.key}`, value: text, option: undefined }],
    })
  }

  return groups
}

/** @deprecated Prefer `AppliedFilterGroup` — kept for any external consumers. */
export type AppliedFilterChip = AppliedFilterValue & {
  urlKey: string
  fieldLabel: string
}

type TranslateFn = (key: string) => string

function readColumnMeta(column: Column<unknown, unknown>): DataTableColumnMeta | undefined {
  return column.columnDef.meta as DataTableColumnMeta | undefined
}

/**
 * Build one group per applied URL filter field, with values nested under the field label.
 * @deprecated Prefer `resolveAppliedFilterGroupsFromDefinitions` (definition-driven, no table instance).
 */
export function resolveAppliedFilterGroups<TData>(
  table: Table<TData>,
  filters: Record<string, string[]> | undefined,
  t: TranslateFn,
): AppliedFilterGroup[] {
  if (!filters) {
    return []
  }

  const groups: AppliedFilterGroup[] = []
  const seenUrlKeys = new Set<string>()

  for (const column of table.getAllColumns()) {
    const meta = readColumnMeta(column as Column<unknown, unknown>)
    const filterConfig = normalizeColumnFilterMeta(meta?.filter)
    if (!filterConfig?.options) {
      continue
    }

    const urlKey = filterConfig.key ?? column.id
    const options = filterConfig.staticOptions ?? []
    if (seenUrlKeys.has(urlKey)) {
      continue
    }
    seenUrlKeys.add(urlKey)

    const appliedValues = filters[urlKey] ?? []
    if (appliedValues.length === 0) {
      continue
    }

    const fieldLabel = resolveColumnLabel(column as Column<unknown, unknown>, t)

    const matchesValue = filterConfig.matchesValue ?? ((applied, option) => applied === option)

    groups.push({
      urlKey,
      fieldLabel,
      values: appliedValues.map((value) => ({
        id: `${urlKey}:${value}`,
        value,
        option: options.find((entry) => matchesValue(value, entry.value)),
      })),
    })
  }

  return groups
}

/**
 * @deprecated Prefer `resolveAppliedFilterGroups`. Flattens groups into per-value chips.
 */
export function resolveAppliedFilterChips<TData>(
  table: Table<TData>,
  filters: Record<string, string[]> | undefined,
  t: TranslateFn,
): AppliedFilterChip[] {
  return resolveAppliedFilterGroups(table, filters, t).flatMap((group) =>
    group.values.map((entry) => ({
      ...entry,
      urlKey: group.urlKey,
      fieldLabel: group.fieldLabel,
    })),
  )
}

/** URL keys that currently have at least one applied filter value. */
export function getActiveFilterUrlKeys(filters: Record<string, string[]> | undefined): string[] {
  if (!filters) {
    return []
  }

  return Object.entries(filters)
    .filter(([, values]) => values.length > 0)
    .map(([key]) => key)
}

import type { Table } from "@tanstack/react-table"
import type { DataTableFilterDefinition } from "../../filter"
import type { DataTableColumnMeta } from "../../view-options"

/**
 * True when the definition is already reachable from a visible column header funnel, so the
 * toolbar should not offer it again. Header-less tables and filter-only cells never count.
 */
export function isFilterInVisibleHeader<TData>(
  definition: DataTableFilterDefinition,
  table: Table<TData>,
  headerFilters: boolean,
): boolean {
  if (!headerFilters || !definition.columnId) {
    return false
  }
  const column = table.getAllLeafColumns().find((entry) => entry.id === definition.columnId)
  if (!column?.getIsVisible()) {
    return false
  }
  const meta = column.columnDef.meta as DataTableColumnMeta | undefined
  return !meta?.filterOnlyCell
}

/**
 * Filters the toolbar ("Add filter" + chips) may offer: any search or value filter whose column
 * is hidden (or has no header), so every field stays filterable without duplicating header funnels.
 */
export function getToolbarFilterDefinitions<TData>(
  definitions: readonly DataTableFilterDefinition[],
  table: Table<TData>,
  headerFilters: boolean,
): DataTableFilterDefinition[] {
  return definitions.filter(
    (definition) =>
      (definition.options !== null || definition.search) && !isFilterInVisibleHeader(definition, table, headerFilters),
  )
}

import { DEFAULT_DATA_TABLE_PAGE_SIZE } from "../constants"

export type EmptyPagedList<T> = {
  items: T[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

/** Empty table payload when a list request has no rows (or no usable envelope). */
export function emptyPagedList<T = never>(page = 1, limit: number = DEFAULT_DATA_TABLE_PAGE_SIZE): EmptyPagedList<T> {
  return {
    items: [],
    pagination: {
      page,
      limit,
      total: 0,
      totalPages: 0,
    },
  }
}

import { getShallowSearchParamsSnapshot } from "./utils-shallow-search-params"

/**
 * Resolve the live listing query string from App Router + document URL.
 *
 * Shallow `history.replaceState` updates the document first; App Router
 * `useSearchParams()` can lag (or lead during in-flight navigations). Merge
 * both sources and let the document win on key conflicts.
 */
export function resolveLiveQueryString(
  serverSearchParams: URLSearchParams,
  liveSearch: string = getShallowSearchParamsSnapshot(),
): string {
  const fromWindow = liveSearch.replace(/^\?/, "")
  if (!fromWindow) {
    return serverSearchParams.toString()
  }

  const merged = new URLSearchParams(serverSearchParams.toString())
  const windowParams = new URLSearchParams(fromWindow)

  for (const key of new Set(windowParams.keys())) {
    merged.delete(key)
    for (const value of windowParams.getAll(key)) {
      merged.append(key, value)
    }
  }

  return merged.toString()
}

/** Build URLSearchParams for client listings (shallow writes + App Router fallback). */
export function createLiveSearchParams(serverSearchParams: URLSearchParams, liveSearch?: string): URLSearchParams {
  return new URLSearchParams(resolveLiveQueryString(serverSearchParams, liveSearch))
}

/** Copy every query entry from `source` into `target` (repeated keys preserved). */
export function mergeSearchParams(target: URLSearchParams, source: URLSearchParams): void {
  for (const key of new Set(source.keys())) {
    for (const value of source.getAll(key)) {
      target.append(key, value)
    }
  }
}

import {
  DATA_TABLE_PAGE_SIZE_STORAGE_KEY,
  type DataTablePageSize,
  DEFAULT_DATA_TABLE_PAGE_SIZE,
  isDataTablePageSize,
} from "../constants"

export function readStoredDataTablePageSize(): DataTablePageSize {
  if (typeof window === "undefined") {
    return DEFAULT_DATA_TABLE_PAGE_SIZE
  }

  try {
    const raw = localStorage.getItem(DATA_TABLE_PAGE_SIZE_STORAGE_KEY)
    if (!raw) {
      return DEFAULT_DATA_TABLE_PAGE_SIZE
    }

    const parsed = Number.parseInt(raw, 10)
    return isDataTablePageSize(parsed) ? parsed : DEFAULT_DATA_TABLE_PAGE_SIZE
  } catch {
    return DEFAULT_DATA_TABLE_PAGE_SIZE
  }
}

export function writeStoredDataTablePageSize(size: DataTablePageSize): void {
  if (typeof window === "undefined") {
    return
  }

  try {
    localStorage.setItem(DATA_TABLE_PAGE_SIZE_STORAGE_KEY, String(size))
  } catch {
    // Quota exceeded, private browsing, or disabled storage.
  }
}

/** Dispatched after `shallowReplaceSearchParams` so React can re-read `window.location.search`. */
export const SHALLOW_SEARCH_PARAMS_EVENT = "feature-kit:shallow-search-params"

export function subscribeShallowSearchParams(onStoreChange: () => void): () => void {
  if (typeof window === "undefined") {
    return () => {}
  }

  const handler = () => {
    onStoreChange()
  }

  window.addEventListener(SHALLOW_SEARCH_PARAMS_EVENT, handler)
  window.addEventListener("popstate", handler)

  return () => {
    window.removeEventListener(SHALLOW_SEARCH_PARAMS_EVENT, handler)
    window.removeEventListener("popstate", handler)
  }
}

export function getShallowSearchParamsSnapshot(): string {
  if (typeof window === "undefined") {
    return ""
  }

  return window.location.search
}

/**
 * Replace the current page query string without a Next.js navigation.
 * Always writes to `window.location` (the visible document), not the hook pathname.
 * Do not block on `usePathname()` lag — that prevented filter clears after client redirects.
 */
export function shallowReplaceSearchParams(_pathname: string, mutate: (params: URLSearchParams) => void): boolean {
  if (typeof window === "undefined") {
    return false
  }

  const current = new URLSearchParams(window.location.search)
  const previousQuery = current.toString()
  mutate(current)

  const query = current.toString()
  if (query === previousQuery) {
    return false
  }

  const nextUrl = query ? `${window.location.pathname}?${query}` : window.location.pathname
  window.history.replaceState(window.history.state, "", `${nextUrl}${window.location.hash}`)
  window.dispatchEvent(new Event(SHALLOW_SEARCH_PARAMS_EVENT))
  return true
}

import { useId } from "react"

/**
 * Generates a stable ID that won't change between server and client renders
 * This prevents hydration mismatches in Radix UI components
 */
export function useStableId(prefix?: string) {
  const reactId = useId()
  return prefix ? `${prefix}-${reactId}` : reactId
}

/**
 * Creates a deterministic ID for a given context
 * Use this when you need predictable IDs across renders
 */
export function createDeterministicId(context: string, suffix?: string) {
  return `${context}${suffix ? `-${suffix}` : ""}`
}

import { createParser, parseAsInteger, parseAsString, parseAsStringLiteral } from "nuqs/server"

import {
  DATA_TABLE_MAX_PAGE_SIZE,
  DATA_TABLE_MIN_PAGE_SIZE,
  DEFAULT_DATA_TABLE_PAGE_SIZE,
  isDataTablePageSize,
} from "../constants"

/** 1-based page index stored in the URL. */
export const parseAsTablePage = parseAsInteger.withDefault(1)

/** Rows per page (`limit`); must match listing validation (20–1000). */
export const parseAsTablePageSize = createParser({
  parse(value) {
    const parsed = Number.parseInt(value, 10)
    if (!Number.isFinite(parsed) || parsed < DATA_TABLE_MIN_PAGE_SIZE || parsed > DATA_TABLE_MAX_PAGE_SIZE) {
      return null
    }
    return isDataTablePageSize(parsed) ? parsed : DEFAULT_DATA_TABLE_PAGE_SIZE
  },
  serialize(value) {
    return String(value)
  },
}).withDefault(DEFAULT_DATA_TABLE_PAGE_SIZE)

export const parseAsTableSearch = parseAsString

export const parseAsTableSortBy = parseAsString

export const parseAsTableSortDir = parseAsStringLiteral(["asc", "desc"] as const)

/** Shared nuqs map for table navigation state owned by the URL. */
export const tableUrlParsers = {
  page: parseAsTablePage,
  limit: parseAsTablePageSize,
  q: parseAsTableSearch,
  sortBy: parseAsTableSortBy,
  sortDir: parseAsTableSortDir,
} as const

/** Client-only URL updates for listing tables (no RSC refetch). */
export const tableUrlShallowUpdateOptions = {
  shallow: true,
  scroll: false,
  /** Keep defaults in the URL so table state is always bookmarkable. */
  clearOnDefault: false,
} as const

/** Trigger a server re-render when table navigation params change. */
export const tableUrlUpdateOptions = {
  shallow: false,
  scroll: false,
  /** Keep defaults in the URL so table state is always bookmarkable. */
  clearOnDefault: false,
} as const

import { normalizeFilterParamValue } from "../column/column-filter-utils"
import {
  DATA_TABLE_MAX_PAGE_SIZE,
  DATA_TABLE_MIN_PAGE_SIZE,
  type DataTablePageSize,
  DEFAULT_DATA_TABLE_PAGE_SIZE,
  isDataTablePageSize,
} from "../constants"
import { columnSearchParamKey } from "../filter/utils/utils-filter-url"

export function parsePageFromSearchParams(searchParams: URLSearchParams): number | null {
  const raw = searchParams.get("page")
  if (raw === null) {
    return null
  }

  const parsed = Number.parseInt(raw, 10)
  if (!Number.isFinite(parsed) || parsed < 1) {
    return null
  }

  return parsed
}

export function parseLimitFromSearchParams(searchParams: URLSearchParams): DataTablePageSize | null {
  const raw = searchParams.get("limit")
  if (raw === null) {
    return null
  }

  const parsed = Number.parseInt(raw, 10)
  if (!Number.isFinite(parsed) || parsed < DATA_TABLE_MIN_PAGE_SIZE || parsed > DATA_TABLE_MAX_PAGE_SIZE) {
    return null
  }

  return isDataTablePageSize(parsed) ? parsed : null
}

export function resolveTablePage(searchParams: URLSearchParams, fallbackPage: number): number {
  return Math.max(1, parsePageFromSearchParams(searchParams) ?? fallbackPage)
}

export function resolveTableLimit(
  searchParams: URLSearchParams,
  fallbackLimit: DataTablePageSize | null | undefined,
): DataTablePageSize {
  return parseLimitFromSearchParams(searchParams) ?? fallbackLimit ?? DEFAULT_DATA_TABLE_PAGE_SIZE
}

/** Apply a column/tab filter write and reset pagination to page 1. */
export function mutateTableFilter(
  params: URLSearchParams,
  key: string,
  value: string | string[] | null | undefined,
): void {
  const values = normalizeFilterParamValue(value)
  params.delete(key)
  for (const entry of values) {
    params.append(key, entry)
  }
  params.set("page", "1")
}

/** Apply pagination without clearing unrelated query keys. */
export function mutateTablePagination(params: URLSearchParams, page: number, limit: number): void {
  params.set("page", String(Math.max(1, page)))
  params.set("limit", String(limit))
}

/** Apply toolbar search and reset pagination to page 1. */
export function mutateTableSearch(params: URLSearchParams, q: string): void {
  const next = q.trim()
  if (next === "") {
    params.delete("q")
  } else {
    params.set("q", next)
  }
  params.set("page", "1")
}

/** Apply a column-specific text search (`cs.<key>`) and reset pagination to page 1. */
export function mutateTableColumnSearch(params: URLSearchParams, key: string, value: string | null | undefined): void {
  const paramKey = columnSearchParamKey(key)
  const next = value?.trim() ?? ""
  if (next === "") {
    params.delete(paramKey)
  } else {
    params.set(paramKey, next)
  }
  params.set("page", "1")
}

/** Apply sort keys and reset pagination to page 1. */
export function mutateTableSorting(
  params: URLSearchParams,
  sortBy: string | null | undefined,
  sortDir: "asc" | "desc" | null | undefined,
): void {
  if (sortBy) {
    params.set("sortBy", sortBy)
  } else {
    params.delete("sortBy")
  }

  if (sortDir) {
    params.set("sortDir", sortDir)
  } else {
    params.delete("sortDir")
  }

  params.set("page", "1")
}

"use client"

import { useEffect, useRef } from "react"

export type DebouncedCallback<TArgs extends unknown[]> = ((...args: TArgs) => void) & {
  cancel: () => void
  flush: () => void
}

/**
 * Trailing-edge debounce: invokes with the latest args after `delayMs` of quiet.
 * Flushes any pending invocation on unmount so the last value is not dropped.
 */
export function useDebouncedCallback<TArgs extends unknown[]>(
  callback: (...args: TArgs) => void,
  delayMs: number,
): DebouncedCallback<TArgs> {
  const callbackRef = useRef(callback)
  const delayRef = useRef(delayMs)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const pendingArgsRef = useRef<TArgs | null>(null)
  const debouncedRef = useRef<DebouncedCallback<TArgs> | null>(null)

  callbackRef.current = callback
  delayRef.current = delayMs

  if (debouncedRef.current === null) {
    const cancel = () => {
      if (timeoutRef.current !== null) {
        clearTimeout(timeoutRef.current)
        timeoutRef.current = null
      }
      pendingArgsRef.current = null
    }

    const flush = () => {
      if (timeoutRef.current !== null) {
        clearTimeout(timeoutRef.current)
        timeoutRef.current = null
      }
      const pending = pendingArgsRef.current
      pendingArgsRef.current = null
      if (pending !== null) {
        callbackRef.current(...pending)
      }
    }

    const run = ((...args: TArgs) => {
      pendingArgsRef.current = args
      if (timeoutRef.current !== null) {
        clearTimeout(timeoutRef.current)
      }
      timeoutRef.current = setTimeout(() => {
        timeoutRef.current = null
        const pending = pendingArgsRef.current
        pendingArgsRef.current = null
        if (pending !== null) {
          callbackRef.current(...pending)
        }
      }, delayRef.current)
    }) as DebouncedCallback<TArgs>

    run.cancel = cancel
    run.flush = flush
    debouncedRef.current = run
  }

  useEffect(() => {
    return () => {
      debouncedRef.current?.flush()
    }
  }, [])

  return debouncedRef.current
}

"use client"

import { useSearchParams } from "next/navigation"
import { useMemo, useSyncExternalStore } from "react"

import { createLiveSearchParams } from "./utils-live-search-params"
import { getShallowSearchParamsSnapshot, subscribeShallowSearchParams } from "./utils-shallow-search-params"

/** App Router search params plus shallow `history.replaceState` updates from listing filters. */
export function useEffectiveSearchParams(): URLSearchParams {
  const searchParams = useSearchParams()
  const liveSearch = useSyncExternalStore(subscribeShallowSearchParams, getShallowSearchParamsSnapshot, () =>
    searchParams.toString(),
  )

  return useMemo(() => {
    if (typeof window === "undefined") {
      return new URLSearchParams(searchParams.toString())
    }

    return createLiveSearchParams(searchParams, liveSearch)
  }, [searchParams, liveSearch])
}

"use client"

import type { DataTablePageSize } from "../constants"

import { hasInFlightAppPathname } from "@/lib/feature-kit/layout/sidebar/app-pathname"
import { usePathname } from "next/navigation"
import { useEffect, useRef } from "react"

import { readStoredDataTablePageSize } from "./utils-page-size-preference"
import { shallowReplaceSearchParams } from "./utils-shallow-search-params"
import { useEffectiveSearchParams } from "./utils-use-effective-search-params"

/**
 * Writes missing table navigation params to the URL on first mount so listings
 * start with a bookmarkable canonical query string (e.g. ?page=1&limit=20).
 * Pass `enabled: false` for embedded tables that own pagination locally.
 */
export function useTableUrlCanonicalize({ enabled = true }: { enabled?: boolean } = {}) {
  const pathname = usePathname()
  const searchParams = useEffectiveSearchParams()
  const didCanonicalize = useRef(false)

  useEffect(() => {
    if (!enabled || didCanonicalize.current || hasInFlightAppPathname(pathname)) {
      return
    }

    const needsPage = !searchParams.has("page")
    const needsLimit = !searchParams.has("limit")

    didCanonicalize.current = true

    if (!needsPage && !needsLimit) {
      return
    }

    shallowReplaceSearchParams(pathname, (current) => {
      if (needsPage) {
        current.set("page", "1")
      }

      if (needsLimit) {
        current.set("limit", String(readStoredDataTablePageSize() as DataTablePageSize))
      }
    })
  }, [enabled, pathname, searchParams])
}

"use client"

import type { Route } from "next"

import { buildDisplayedAppHref } from "@/lib/feature-kit/layout/sidebar/app-pathname"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import { useQueryStates } from "nuqs"
import { useCallback, useMemo } from "react"

import { DATA_TABLE_CLEAR_FILTER_URL_KEYS, isDataTablePageSize } from "../constants"
import { mergeSearchParams } from "./utils-live-search-params"
import { shallowReplaceSearchParams } from "./utils-shallow-search-params"
import { tableUrlParsers, tableUrlShallowUpdateOptions, tableUrlUpdateOptions } from "./utils-table-url-parsers"
import {
  mutateTableColumnSearch,
  mutateTableFilter,
  mutateTablePagination,
  mutateTableSearch,
  mutateTableSorting,
  resolveTableLimit,
  resolveTablePage,
} from "./utils-table-url-sync.utils"
import { useEffectiveSearchParams } from "./utils-use-effective-search-params"

/** Listing URL write/read strategy — one mode per route, no mixed shallow + refresh. */
export type TableUrlListingMode = "clientQuery" | "serverRsc" | "cascadeClientQuery"

export type TableUrlSyncOptions = {
  /**
   * Preferred listing mode. Overrides ad-hoc `shallow` / `serverRefresh` when set.
   *
   * - `clientQuery` / `cascadeClientQuery` — shallow `replaceState`; client queries read merged URL
   * - `serverRsc` — `router.replace` + RSC refresh (IAM server listings)
   */
  mode?: TableUrlListingMode
  /**
   * When true (default for client listings), URL writes use `history.replaceState` without an RSC refetch.
   * Ignored when `mode` is set.
   */
  shallow?: boolean
  /** After URL writes, re-fetch server components. Ignored when `mode` is set. */
  serverRefresh?: boolean
}

export function resolveTableUrlSyncOptions(options?: TableUrlSyncOptions): {
  shallow: boolean
  serverRefresh: boolean
} {
  if (options?.mode) {
    switch (options.mode) {
      case "clientQuery":
      case "cascadeClientQuery":
        return { shallow: true, serverRefresh: false }
      case "serverRsc":
        return { shallow: false, serverRefresh: true }
    }
  }

  const serverRefresh = options?.serverRefresh ?? false
  const shallow = options?.shallow ?? !serverRefresh
  return { shallow, serverRefresh }
}

export function useTableUrlSync(options?: TableUrlSyncOptions) {
  const { shallow, serverRefresh } = resolveTableUrlSyncOptions(options)
  const updateOptions = shallow ? tableUrlShallowUpdateOptions : tableUrlUpdateOptions
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const effectiveSearchParams = useEffectiveSearchParams()
  const readParams = shallow ? effectiveSearchParams : searchParams

  const refreshServer = useCallback(() => {
    if (serverRefresh) {
      router.refresh()
    }
  }, [router, serverRefresh])

  // nuqs backs non-shallow navigations; shallow listings read/write the live query string.
  const [tableParams, setTableParams] = useQueryStates(tableUrlParsers, updateOptions)

  const page = useMemo(() => {
    return resolveTablePage(readParams, tableParams.page)
  }, [readParams, tableParams.page])

  const limit = useMemo(() => {
    return resolveTableLimit(readParams, tableParams.limit)
  }, [readParams, tableParams.limit])

  const pushSearchParams = useCallback(
    (mutate: (params: URLSearchParams) => void) => {
      if (shallow) {
        const didWrite = shallowReplaceSearchParams(pathname, (current) => {
          if (!current.toString() && readParams.toString()) {
            mergeSearchParams(current, readParams)
          }
          mutate(current)
        })
        if (didWrite) {
          refreshServer()
        }
        return
      }

      const current = new URLSearchParams(
        typeof window === "undefined" ? Array.from(searchParams.entries()) : window.location.search,
      )
      mutate(current)
      const href = buildDisplayedAppHref(pathname, current.toString())
      if (href === null) return
      router.replace(href as Route, { scroll: false })
      refreshServer()
    },
    [pathname, readParams, refreshServer, router, searchParams, shallow],
  )

  const setFilter = useCallback(
    (key: string, value: string | string[] | null | undefined) => {
      pushSearchParams((current) => {
        mutateTableFilter(current, key, value)
      })
    },
    [pushSearchParams],
  )

  const setColumnSearch = useCallback(
    (key: string, value: string | null | undefined) => {
      pushSearchParams((current) => {
        mutateTableColumnSearch(current, key, value)
      })
    },
    [pushSearchParams],
  )

  const setPagination = useCallback(
    (nextPage: number, nextLimit: number) => {
      if (!isDataTablePageSize(nextLimit)) {
        return
      }

      const normalizedPage = Math.max(1, nextPage)

      if (shallow) {
        pushSearchParams((current) => {
          mutateTablePagination(current, normalizedPage, nextLimit)
        })
        return
      }

      void setTableParams({
        page: normalizedPage,
        limit: nextLimit,
      })
      refreshServer()
    },
    [pushSearchParams, refreshServer, setTableParams, shallow],
  )

  const setSearch = useCallback(
    (q: string) => {
      const next = q.trim()

      if (shallow) {
        pushSearchParams((current) => {
          mutateTableSearch(current, q)
        })
        return
      }

      void setTableParams({
        q: next === "" ? null : next,
        page: 1,
      })
      refreshServer()
    },
    [pushSearchParams, refreshServer, setTableParams, shallow],
  )

  const setSorting = useCallback(
    (sortBy: string | null | undefined, sortDir: "asc" | "desc" | null | undefined) => {
      if (shallow) {
        pushSearchParams((current) => {
          mutateTableSorting(current, sortBy, sortDir)
        })
        return
      }

      void setTableParams({
        sortBy: sortBy ?? null,
        sortDir: sortDir ?? null,
        page: 1,
      })
      refreshServer()
    },
    [pushSearchParams, refreshServer, setTableParams, shallow],
  )

  const clearFilters = useCallback(
    (keysToRemove?: string[]) => {
      pushSearchParams((current) => {
        const keys = keysToRemove && keysToRemove.length > 0 ? keysToRemove : DATA_TABLE_CLEAR_FILTER_URL_KEYS
        for (const key of keys) {
          current.delete(key)
        }
        current.set("page", "1")
      })
    },
    [pushSearchParams],
  )

  return {
    page,
    limit,
    pageIndex: page - 1,
    setFilter,
    setColumnSearch,
    setPagination,
    setSearch,
    setSorting,
    clearFilters,
  }
}

"use client"

import { useSyncExternalStore } from "react"

const emptySubscribe = () => () => {}

/**
 * Avoids hydration mismatch while column visibility restores from localStorage.
 * Server snapshot is false (generic label); client snapshot is true immediately.
 */
export function useViewOptionsMounted() {
  return useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false,
  )
}

/** Legacy localStorage key prefix (visibility only). */
export const VIEW_OPTIONS_STORAGE_KEY_PREFIX_V1 = "data-table:columns:v1:"

/** Versioned localStorage key prefix for per-table column preferences. */
export const VIEW_OPTIONS_STORAGE_KEY_PREFIX = "data-table:columns:v2:"

/** Columns that cannot be hidden, reordered, or pinned from the column manager. */
export const LOCKED_COLUMN_IDS = new Set<string>(["expand", "select", "actions"])

/** Width of compact icon sticky columns (`w-10`). */
export const ICON_STICKY_COLUMN_WIDTH_PX = 40

/** Fallback width when a pinned data column has no explicit size. */
export const DEFAULT_PINNED_DATA_COLUMN_WIDTH_PX = 150

"use client"

import type { DragEndEvent } from "@dnd-kit/core"
import type { ViewOptionsColumnItem, ViewOptionsDraft } from "./view-options-types"

import { closestCenter, DndContext, KeyboardSensor, PointerSensor, useSensor, useSensors } from "@dnd-kit/core"
import { arrayMove, SortableContext, sortableKeyboardCoordinates, verticalListSortingStrategy } from "@dnd-kit/sortable"
import { Lock, Search } from "lucide-react"
import { useTranslations } from "next-intl"
import { useRef, useState } from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group"
import { Label } from "@/components/ui/label"
import { Separator } from "@/components/ui/separator"
import { cn } from "@/lib/utils"

import { ViewOptionsSortableItem } from "./view-options-sortable-item"
import { filterOptionalColumns, orderOptionalColumns } from "./view-options-utils"

export type ViewOptionsPanelProps = {
  alwaysOn: ViewOptionsColumnItem[]
  optional: ViewOptionsColumnItem[]
  draft: ViewOptionsDraft
  search: string
  onSearchChange: (value: string) => void
  onDraftChange: (draft: ViewOptionsDraft) => void
  onShowAll: () => void
  onCancel: () => void
  onReset: () => void
  onSave: () => void
  className?: string
}

export function ViewOptionsPanel({
  alwaysOn,
  optional,
  draft,
  search,
  onSearchChange,
  onDraftChange,
  onShowAll,
  onCancel,
  onReset,
  onSave,
  className,
}: ViewOptionsPanelProps) {
  const t = useTranslations()
  const [isDragging, setIsDragging] = useState(false)
  const suppressPinClickRef = useRef(false)
  const filteredOptional = filterOptionalColumns(optional, search)
  const orderedOptional = orderOptionalColumns(filteredOptional, draft.order)
  const dragDisabled = search.trim().length > 0

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  const handleDragStart = () => {
    setIsDragging(true)
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event

    // Block pin-button clicks before re-enabling row interactions (mouseup can synthesize a click).
    suppressPinClickRef.current = true
    window.setTimeout(() => {
      suppressPinClickRef.current = false
    }, 0)
    setIsDragging(false)

    if (!over || active.id === over.id) {
      return
    }

    const activeId = String(active.id)
    const overId = String(over.id)
    const oldIndex = draft.order.indexOf(activeId)
    const newIndex = draft.order.indexOf(overId)

    if (oldIndex < 0 || newIndex < 0) {
      return
    }

    onDraftChange({
      ...draft,
      order: arrayMove(draft.order, oldIndex, newIndex),
    })
  }

  const handleDragCancel = () => {
    suppressPinClickRef.current = true
    window.setTimeout(() => {
      suppressPinClickRef.current = false
    }, 0)
    setIsDragging(false)
  }

  const handleVisibilityChange = (columnId: string, visible: boolean) => {
    onDraftChange({
      ...draft,
      visibility: { ...draft.visibility, [columnId]: visible },
    })
  }

  const handlePinToggle = (columnId: string) => {
    if (suppressPinClickRef.current) {
      return
    }

    const isPinned = draft.pinnedLeft.includes(columnId)
    onDraftChange({
      ...draft,
      pinnedLeft: isPinned ? draft.pinnedLeft.filter((id) => id !== columnId) : [...draft.pinnedLeft, columnId],
    })
  }

  return (
    <div className={cn("flex min-h-0 flex-col gap-3", className)}>
      <InputGroup className="bg-surface shadow-xs">
        <InputGroupAddon align="inline-start">
          <Search />
        </InputGroupAddon>
        <InputGroupInput
          value={search}
          onChange={(event) => onSearchChange(event.target.value)}
          placeholder={t("dataTable.view.searchPlaceholder")}
          aria-label={t("dataTable.view.searchPlaceholder")}
        />
      </InputGroup>

      <div className="flex max-h-96 min-h-0 flex-col gap-3 overflow-y-auto px-1">
        {alwaysOn.length > 0 ? (
          <section className="flex flex-col gap-2">
            <div className="flex flex-col gap-0.5">
              <h3 className="font-medium text-muted-foreground text-xs uppercase tracking-wide">
                {t("dataTable.view.alwaysOn")}
              </h3>
              <p className="text-muted-foreground text-xs">{t("dataTable.view.alwaysOnHint")}</p>
            </div>
            <ul className="flex flex-col gap-1.5">
              {alwaysOn.map((column) => (
                <li
                  key={column.id}
                  className="flex items-center gap-2 rounded-md px-1 py-1 opacity-70">
                  <span
                    className="size-7 shrink-0"
                    aria-hidden
                  />
                  <Checkbox
                    id={`view-options-locked-${column.id}`}
                    checked
                    disabled
                    aria-label={column.label}
                  />
                  <Label
                    htmlFor={`view-options-locked-${column.id}`}
                    className="flex min-w-0 flex-1 cursor-not-allowed items-center justify-between gap-2 font-normal">
                    <span className="truncate">{column.label}</span>
                    <Lock
                      className="size-3.5 shrink-0 text-muted-foreground"
                      aria-hidden
                    />
                  </Label>
                  <span
                    className="size-7 shrink-0"
                    aria-hidden
                  />
                </li>
              ))}
            </ul>
          </section>
        ) : null}

        {alwaysOn.length > 0 && optional.length > 0 ? <Separator /> : null}

        <section className="flex flex-col gap-2">
          <div className="flex items-center justify-between gap-2">
            <div className="flex flex-col gap-0.5">
              <h3 className="font-medium text-muted-foreground text-xs uppercase tracking-wide">
                {t("dataTable.view.optional")}
              </h3>
              <p className="text-muted-foreground text-xs">{t("dataTable.view.optionalHint")}</p>
            </div>
            {optional.length > 0 ? (
              <Button
                type="button"
                variant="ghost"
                size="xs"
                className="h-6 shrink-0 px-2 text-xs"
                onClick={onShowAll}>
                {t("dataTable.view.showAll")}
              </Button>
            ) : null}
          </div>

          {orderedOptional.length === 0 ? (
            <p className="px-1 py-2 text-muted-foreground text-xs">{t("dataTable.view.emptySearch")}</p>
          ) : (
            <DndContext
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragStart={handleDragStart}
              onDragCancel={handleDragCancel}
              onDragEnd={handleDragEnd}>
              <SortableContext
                items={orderedOptional.map((column) => column.id)}
                strategy={verticalListSortingStrategy}>
                <ul className="flex flex-col gap-1.5">
                  {orderedOptional.map((column) => (
                    <ViewOptionsSortableItem
                      key={column.id}
                      column={column}
                      checked={draft.visibility[column.id] !== false}
                      pinned={draft.pinnedLeft.includes(column.id)}
                      dragDisabled={dragDisabled}
                      interactionsDisabled={isDragging}
                      onCheckedChange={(visible) => handleVisibilityChange(column.id, visible)}
                      onPinToggle={() => handlePinToggle(column.id)}
                    />
                  ))}
                </ul>
              </SortableContext>
            </DndContext>
          )}
        </section>
      </div>

      <Separator />

      <div className="flex items-center justify-end gap-2 px-1">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={onCancel}>
          {t("dataTable.view.cancel")}
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={onReset}>
          {t("dataTable.view.reset")}
        </Button>
        <Button
          type="button"
          size="sm"
          onClick={onSave}>
          {t("dataTable.view.save")}
        </Button>
      </div>
    </div>
  )
}

import type { VisibilityState } from "@tanstack/react-table"
import type { StoredColumnPreferences } from "./view-options-types"

import {
  LOCKED_COLUMN_IDS,
  VIEW_OPTIONS_STORAGE_KEY_PREFIX,
  VIEW_OPTIONS_STORAGE_KEY_PREFIX_V1,
} from "./view-options-constants"
import { mergeColumnOrder } from "./view-options-utils"

export function getViewOptionsStorageKey(tableId: string): string {
  return `${VIEW_OPTIONS_STORAGE_KEY_PREFIX}${tableId}`
}

function getViewOptionsStorageKeyV1(tableId: string): string {
  return `${VIEW_OPTIONS_STORAGE_KEY_PREFIX_V1}${tableId}`
}

function isVisibilityState(value: unknown): value is VisibilityState {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return false
  }

  for (const entry of Object.values(value)) {
    if (typeof entry !== "boolean") {
      return false
    }
  }

  return true
}

function parseStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined
  }

  return value.filter((entry): entry is string => typeof entry === "string" && entry.length > 0)
}

function parseStoredPreferences(raw: unknown): StoredColumnPreferences | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return null
  }

  const record = raw as Record<string, unknown>

  if (isVisibilityState(record)) {
    return { visibility: record }
  }

  if (!isVisibilityState(record["visibility"])) {
    return null
  }

  const preferences: StoredColumnPreferences = {
    visibility: record["visibility"] as VisibilityState,
  }

  const order = parseStringArray(record["order"])
  if (order !== undefined) {
    preferences.order = order
  }

  const pinnedLeft = parseStringArray(record["pinnedLeft"])
  if (pinnedLeft !== undefined) {
    preferences.pinnedLeft = pinnedLeft
  }

  return preferences
}

function readRawPreferences(tableId: string): StoredColumnPreferences | null {
  if (typeof window === "undefined" || !tableId) {
    return null
  }

  try {
    const v2Raw = localStorage.getItem(getViewOptionsStorageKey(tableId))
    if (v2Raw) {
      return parseStoredPreferences(JSON.parse(v2Raw))
    }

    const v1Raw = localStorage.getItem(getViewOptionsStorageKeyV1(tableId))
    if (!v1Raw) {
      return null
    }

    return parseStoredPreferences(JSON.parse(v1Raw))
  } catch {
    return null
  }
}

/**
 * Read stored column preferences for a table.
 * Returns `null` when missing, invalid, or storage is unavailable.
 */
export function readStoredColumnPreferences(tableId: string): StoredColumnPreferences | null {
  return readRawPreferences(tableId)
}

/** @deprecated Use `readStoredColumnPreferences`. */
export function readStoredColumnVisibility(tableId: string): VisibilityState | null {
  return readStoredColumnPreferences(tableId)?.visibility ?? null
}

/** Persist column preferences for a table. No-ops on failure. */
export function writeStoredColumnPreferences(tableId: string, preferences: StoredColumnPreferences): void {
  if (typeof window === "undefined" || !tableId) {
    return
  }

  try {
    localStorage.setItem(getViewOptionsStorageKey(tableId), JSON.stringify(preferences))
    localStorage.removeItem(getViewOptionsStorageKeyV1(tableId))
  } catch {
    // Quota exceeded, private browsing, or disabled storage.
  }
}

/** @deprecated Use `writeStoredColumnPreferences`. */
export function writeStoredColumnVisibility(tableId: string, visibility: VisibilityState): void {
  writeStoredColumnPreferences(tableId, { visibility })
}

/**
 * Keep only visibility entries for known column ids.
 * Unknown ids (removed columns) are dropped.
 */
export function mergeStoredVisibility(stored: VisibilityState | null, columnIds: readonly string[]): VisibilityState {
  if (!stored) {
    return {}
  }

  const allowed = new Set(columnIds)
  const result: VisibilityState = {}
  for (const [id, visible] of Object.entries(stored)) {
    if (allowed.has(id) && typeof visible === "boolean") {
      result[id] = visible
    }
  }
  return result
}

function getHideableColumnIds(columnIds: readonly string[]): string[] {
  return columnIds.filter((id) => !LOCKED_COLUMN_IDS.has(id))
}

/** Merge stored preferences with known column ids. */
export function mergeStoredPreferences(
  stored: StoredColumnPreferences | null,
  columnIds: readonly string[],
): StoredColumnPreferences {
  const hideableIds = getHideableColumnIds(columnIds)
  const visibility = mergeStoredVisibility(stored?.visibility ?? null, hideableIds)
  const order = mergeColumnOrder(hideableIds, stored?.order ?? hideableIds)
  const pinnedLeft = (stored?.pinnedLeft ?? []).filter((id) => hideableIds.includes(id) && order.includes(id))

  return { visibility, order, pinnedLeft }
}

/** Merge table defaults with stored visibility. Stored wins; defaults apply for columns missing from storage. */
export function mergeDefaultColumnVisibility(
  defaults: VisibilityState,
  stored: VisibilityState | null,
  columnIds: readonly string[],
): VisibilityState {
  const result: VisibilityState = {}

  for (const id of columnIds) {
    if (stored && id in stored) {
      const storedValue = stored[id]
      if (typeof storedValue === "boolean") {
        result[id] = storedValue
      }
      continue
    }

    if (id in defaults) {
      const defaultValue = defaults[id]
      if (typeof defaultValue === "boolean") {
        result[id] = defaultValue
      }
    }
  }

  return result
}

export type ResolvedColumnPreferences = {
  visibility: VisibilityState
  order: string[]
  pinnedLeft: string[]
}

export type ColumnPreferenceDefaults = {
  visibility?: VisibilityState
  pinnedLeft?: string[]
}

/** Resolve initial preferences from storage and defaults. Client-only — call after mount. */
export function resolveInitialColumnPreferences(
  tableId: string | undefined,
  columnIds: readonly string[],
  defaults: ColumnPreferenceDefaults = {},
): ResolvedColumnPreferences {
  const hideableIds = getHideableColumnIds(columnIds)
  const defaultPinnedLeft = (defaults.pinnedLeft ?? []).filter(
    (id) => hideableIds.includes(id) && !LOCKED_COLUMN_IDS.has(id),
  )

  if (!tableId) {
    return {
      visibility: defaults.visibility ?? {},
      order: hideableIds,
      pinnedLeft: defaultPinnedLeft,
    }
  }

  const rawStored = readStoredColumnPreferences(tableId)
  const stored = mergeStoredPreferences(rawStored, columnIds)
  const visibility = mergeDefaultColumnVisibility(defaults.visibility ?? {}, stored.visibility, hideableIds)
  const pinnedLeft = rawStored && "pinnedLeft" in rawStored ? (stored.pinnedLeft ?? []) : defaultPinnedLeft

  return {
    visibility,
    order: stored.order ?? hideableIds,
    pinnedLeft,
  }
}

/** @deprecated Use `resolveInitialColumnPreferences`. */
export function resolveInitialColumnVisibility(
  tableId: string | undefined,
  columnIds: readonly string[],
  defaults: VisibilityState = {},
): VisibilityState {
  return resolveInitialColumnPreferences(tableId, columnIds, { visibility: defaults }).visibility
}

