import { useFormatter } from "next-intl"

/**
 * Extended formatters that wrap next-intl to provide typed semantic formats
 * and extra domain formatters (like FileSize, Phone).
 */
export function useFormat() {
  const formatter = useFormatter()

  return {
    ...formatter,
    // Add custom wrapper functions here if needed to ensure strictly typed formats
    // e.g. file size, phone number, address.
    fileSize: (bytes: number) => {
      // Stub implementation. Can use next-intl messages or standard math.
      const mb = bytes / (1024 * 1024)
      return `${formatter.number(mb, { maximumFractionDigits: 2 })} MB`
    },
    phone: (number: string) => {
      // Stub implementation
      return number
    },
  }
}

/** Character shown in place of hidden characters. */
export const MASK_CHAR = "•"

/**
 * Hidden characters are always shown as this many bullets, whatever the real
 * length — a length-preserving mask still discloses the length.
 */
export const MASK_WIDTH = 4

const MASK = MASK_CHAR.repeat(MASK_WIDTH)

/**
 * Masks one label for display: first and last character around a fixed-width
 * mask. Labels of three characters or fewer keep only the first character, so
 * a short local part is never reconstructable.
 */
export function maskLabel(label: string): string {
  const chars = [...label]
  if (chars.length === 0) return ""
  if (chars.length <= 3) return `${chars[0]}${MASK}`
  return `${chars[0]}${MASK}${chars[chars.length - 1]}`
}

/**
 * DPDP-safe display form of an email address.
 *
 * `user@example.com` → `j••••t@a••••n.ai`: first and last character of
 * the local part and of each domain label are kept, the top-level domain is
 * kept whole so the address still reads as an address. Only for DISPLAY —
 * never feed the result back into a lookup.
 *
 * Returns "" for empty input and masks the whole value when it is not an
 * email (no `@`), so a malformed claim never leaks through unmasked.
 */
export function maskEmail(value: string | null | undefined): string {
  const email = value?.trim() ?? ""
  if (!email) return ""

  const at = email.lastIndexOf("@")
  if (at <= 0 || at === email.length - 1) return maskLabel(email)

  const local = email.slice(0, at)
  const labels = email.slice(at + 1).split(".")
  const tld = labels.length > 1 ? labels.pop() : undefined
  const domain = labels.map(maskLabel).join(".")

  return `${maskLabel(local)}@${domain}${tld ? `.${tld}` : ""}`
}

import type { Formats } from "next-intl"
import type { AppPreferences } from "@/lib/feature-kit/preferences"

import { defaultLocale, resolveEffectivePreferences } from "./effective-preferences"

export function createSemanticFormats(prefs: AppPreferences, locale: string = defaultLocale): Formats {
  const effective = resolveEffectivePreferences(prefs, locale)
  const customDateStyle = effective.dateStyle
  const customTimeStyle = effective.timeStyle
  const customHourCycle = effective.hourCycle

  return {
    dateTime: {
      short: {
        dateStyle: customDateStyle ?? "short",
        timeStyle: customTimeStyle ?? "short",
        ...(customHourCycle ? { hourCycle: customHourCycle } : {}),
      },
      medium: {
        dateStyle: customDateStyle ?? "medium",
        timeStyle: customTimeStyle ?? "medium",
        ...(customHourCycle ? { hourCycle: customHourCycle } : {}),
      },
      long: {
        dateStyle: customDateStyle ?? "long",
        timeStyle: customTimeStyle ?? "long",
        ...(customHourCycle ? { hourCycle: customHourCycle } : {}),
      },
      compact: { month: "numeric", day: "numeric", year: "2-digit" },
      table: {
        dateStyle: customDateStyle ?? "medium",
        timeStyle: customTimeStyle ?? "short",
        ...(customHourCycle ? { hourCycle: customHourCycle } : {}),
      },
      dateOnly: {
        dateStyle: customDateStyle ?? "medium",
      },
      audit: {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        fractionalSecondDigits: 3,
        ...(customHourCycle && { hourCycle: customHourCycle }),
      },
      tooltip: { dateStyle: customDateStyle ?? "full", timeStyle: customTimeStyle ?? "long" },
      relative: {
        /* Relative time is generally handled by format.relativeTime */
      },
      calendar: {
        /* Depending on how next-intl supports calendar strings */
      },
      shortDateTime: {
        dateStyle: customDateStyle ?? "short",
        timeStyle: customTimeStyle ?? "short",
        ...(customHourCycle ? { hourCycle: customHourCycle } : {}),
      },
      longDateTime: {
        dateStyle: customDateStyle ?? "long",
        timeStyle: customTimeStyle ?? "long",
        ...(customHourCycle ? { hourCycle: customHourCycle } : {}),
      },
      time12: { hour: "numeric", minute: "2-digit", hour12: true },
      time24: { hour: "2-digit", minute: "2-digit", hour12: false },
      timeWithSeconds: {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        ...(customHourCycle && { hourCycle: customHourCycle }),
      },
      filename: {
        /* Filename dates usually need custom non-intl logic, but we can set up ISO components */
      },
      inputDate: { year: "numeric", month: "2-digit", day: "2-digit" },
      inputDateTime: { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" },
      month: { month: "long" },
      monthYear: { month: "long", year: "numeric" },
      weekday: { weekday: "long" },
      year: { year: "numeric" },
    },
    number: {
      decimal: { minimumFractionDigits: 0, maximumFractionDigits: 2 },
      table: { minimumFractionDigits: 2, maximumFractionDigits: 2 },
      percentage: { style: "percent", minimumFractionDigits: 1 },
      currency: {
        style: "currency",
        currency: effective.currency ?? "INR",
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      },
      ordinal: {
        /* Requires plural categories usually */
      },
    },
    list: {
      standard: { type: "conjunction" },
    },
  }
}

