"use client"

import type { ComponentProps } from "react"

import { useFormat } from "../hooks"
import { parseDisplayDate } from "./cells.utils"

const PLACEHOLDER = "-"

/** Intl dateStyle values — format date-only (pair with TimeCell for stacked columns). */
const DATE_STYLE_FORMATS = new Set<string>(["full", "long", "medium", "short"])

type CellProps<T> = {
  value?: T | null
  format?: string
  fallback?: React.ReactNode
} & Omit<ComponentProps<"span">, "children">

export function DateCell({
  value,
  format = "medium",
  fallback = PLACEHOLDER,
  ...props
}: CellProps<Date | string | number>) {
  const formatter = useFormat()
  if (!value) return <span {...props}>{fallback}</span>

  try {
    const date = parseDisplayDate(value, format)
    if (!date) return <span {...props}>{fallback}</span>
    const formatted = DATE_STYLE_FORMATS.has(format)
      ? formatter.dateTime(date, { dateStyle: format as NonNullable<Intl.DateTimeFormatOptions["dateStyle"]> })
      : formatter.dateTime(date, format)
    return <span {...props}>{formatted}</span>
  } catch {
    return <span {...props}>{fallback}</span>
  }
}

export function NumberCell({
  value,
  format = "decimal",
  fallback = PLACEHOLDER,
  ...props
}: CellProps<number | bigint | string>) {
  const formatter = useFormat()
  if (value == null) return <span {...props}>{fallback}</span>

  try {
    const num = Number(value)
    if (Number.isNaN(num)) return <span {...props}>{fallback}</span>
    return <span {...props}>{formatter.number(num, format)}</span>
  } catch {
    return <span {...props}>{fallback}</span>
  }
}

export function CurrencyCell({
  value,
  format = "currency",
  fallback = PLACEHOLDER,
  ...props
}: CellProps<number | bigint | string>) {
  const formatter = useFormat()
  if (value == null) return <span {...props}>{fallback}</span>

  try {
    const num = Number(value)
    if (Number.isNaN(num)) return <span {...props}>{fallback}</span>
    return <span {...props}>{formatter.number(num, format)}</span>
  } catch {
    return <span {...props}>{fallback}</span>
  }
}

export function TimeCell({
  value,
  format = "short",
  fallback = PLACEHOLDER,
  ...props
}: CellProps<Date | string | number>) {
  const formatter = useFormat()
  if (!value) return <span {...props}>{fallback}</span>

  try {
    const date = new Date(value)
    if (Number.isNaN(date.getTime())) return <span {...props}>{fallback}</span>
    // Next-intl format.dateTime can take timeStyle
    return (
      <span {...props}>
        {formatter.dateTime(date, { timeStyle: format as NonNullable<Intl.DateTimeFormatOptions["timeStyle"]> })}
      </span>
    )
  } catch {
    return <span {...props}>{fallback}</span>
  }
}

export function DateTimeCell({
  value,
  format = "shortDateTime",
  fallback = PLACEHOLDER,
  ...props
}: CellProps<Date | string | number>) {
  const formatter = useFormat()
  if (!value) return <span {...props}>{fallback}</span>

  try {
    const date = new Date(value)
    if (Number.isNaN(date.getTime())) return <span {...props}>{fallback}</span>
    return <span {...props}>{formatter.dateTime(date, format)}</span>
  } catch {
    return <span {...props}>{fallback}</span>
  }
}

// Stub for other cells (RelativeTimeCell, PercentageCell, FileSizeCell, PhoneCell, EmailCell, BooleanBadge, StatusBadge, LinkCell)
// which can be expanded by the team.

export function parseYearMonth(value: string): Date | null {
  const match = /^(\d{4})-(\d{2})/.exec(value)
  if (!match) return null
  const year = Number(match[1])
  const month = Number(match[2])
  if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) return null
  const date = new Date(year, month - 1, 1)
  return Number.isNaN(date.getTime()) ? null : date
}

export function parseDisplayDate(value: Date | string | number, format: string): Date | null {
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value
  if (typeof value === "string") {
    const trimmed = value.trim()
    if (format === "monthYear" || format === "month") {
      const monthYear = parseYearMonth(trimmed)
      if (monthYear) return monthYear
    }
    if (format === "year") {
      const yearMatch = /^(\d{4})/.exec(trimmed)
      if (yearMatch) {
        const year = Number(yearMatch[1])
        if (Number.isInteger(year)) {
          const date = new Date(year, 0, 1)
          return Number.isNaN(date.getTime()) ? null : date
        }
      }
    }
    const useCalendarDate = format === "dateOnly" || /^\d{4}-\d{2}-\d{2}$/.test(trimmed)
    if (useCalendarDate) {
      const ymd = /^(\d{4}-\d{2}-\d{2})/.exec(trimmed)?.[1]
      if (ymd) {
        const [yearText, monthText, dayText] = ymd.split("-")
        const year = Number(yearText)
        const month = Number(monthText)
        const day = Number(dayText)
        if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) return null
        const date = new Date(year, month - 1, day)
        return Number.isNaN(date.getTime()) ? null : date
      }
    }
  }
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? null : date
}

import type { AppPreferences } from "@/lib/feature-kit/preferences"
import type { RegionalProfile } from "../effective-preferences-types"

import {
  defaultCurrency,
  defaultDateStyle,
  defaultLocale,
  defaultTimeStyle,
  defaultTimeZone,
  regionalProfiles,
} from "../constants"

export function getRegionalProfileForLocale(locale: string): RegionalProfile {
  return regionalProfiles.find((profile) => profile.locale === locale) ?? (regionalProfiles[0] as RegionalProfile)
}

/**
 * Merge cookie preferences with locale-derived regional defaults, then global i18n fallbacks.
 * Explicit cookie values win; missing fields are filled from the locale profile.
 */
export function resolveEffectivePreferences(prefs: AppPreferences, locale: string = defaultLocale): AppPreferences {
  const profile = getRegionalProfileForLocale(locale)
  const regional = profile.defaultFormats ?? {}

  const resolved: AppPreferences = {
    ...prefs,
    currency: prefs.currency ?? regional.currency ?? profile.currency ?? defaultCurrency,
    timezone: prefs.timezone ?? regional.timezone ?? profile.defaultTimeZone ?? defaultTimeZone,
    dateStyle: prefs.dateStyle ?? regional.dateStyle ?? defaultDateStyle,
    timeStyle: prefs.timeStyle ?? regional.timeStyle ?? defaultTimeStyle,
  }

  const hourCycle = prefs.hourCycle ?? regional.hourCycle
  if (hourCycle) {
    resolved.hourCycle = hourCycle
  }

  const firstDayOfWeek = prefs.firstDayOfWeek ?? regional.firstDayOfWeek
  if (firstDayOfWeek !== undefined) {
    resolved.firstDayOfWeek = firstDayOfWeek
  }

  if (
    !resolved.locale &&
    (locale === "en-IN" || locale === "hi-IN" || locale === "ur-IN" || locale === "en-US" || locale === "en-GB")
  ) {
    resolved.locale = locale
  }

  return resolved
}

export type ExportDateTimeFormat = "table" | "dateOnly"

export type ExportDateTimeFormatter = {
  dateTime: (value: Date, format: ExportDateTimeFormat) => string
}

export type ExportDateFormatters = {
  dateTime: (value: Date | string | number | null | undefined) => string
  date: (value: Date | string | number | null | undefined) => string
}

export function formatExportDateTime(
  formatter: ExportDateTimeFormatter,
  value: Date | string | number | null | undefined,
  format: ExportDateTimeFormat = "table",
): string {
  if (value == null || value === "") return ""

  try {
    const date = new Date(value)
    if (Number.isNaN(date.getTime())) return ""
    return formatter.dateTime(date, format)
  } catch {
    return ""
  }
}

export function createExportDateFormatters(formatter: ExportDateTimeFormatter): ExportDateFormatters {
  return {
    dateTime: (value) => formatExportDateTime(formatter, value, "table"),
    date: (value) => formatExportDateTime(formatter, value, "dateOnly"),
  }
}

export type ExportFormatter = {
  dateTime: (value: Date, format: string) => string
  number: (value: number, format: string) => string
}

export type ExportNumberFormatter = Pick<ExportFormatter, "number">

export type ExportMonthYearFormatter = Pick<ExportFormatter, "dateTime">

export function formatExportCurrency(
  formatter: ExportNumberFormatter,
  value: number | string | null | undefined,
): string {
  if (value == null || value === "") return ""
  const num = typeof value === "number" ? value : Number(value)
  if (Number.isNaN(num)) return String(value)

  try {
    return formatter.number(num, "currency")
  } catch {
    return String(num)
  }
}

export function formatExportMonthYear(formatter: ExportMonthYearFormatter, period: string | null | undefined): string {
  if (!period) return ""
  const match = /^(\d{4})-(\d{2})$/.exec(period.trim())
  if (!match) return period

  const year = Number(match[1])
  const month = Number(match[2])
  if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) return period

  try {
    return formatter.dateTime(new Date(year, month - 1, 1), "monthYear")
  } catch {
    return period
  }
}
